import { computed, inject, nextTick, onActivated, onBeforeUnmount, onDeactivated, onMounted, shallowRef, watch, type Ref } from 'vue'
import { getBotsByBotIdTtsPlaybackConfig, postBotsByBotIdTtsPlaybackInput, putBotsByBotIdTtsPlaybackInput } from '@memohai/sdk'
import { useLocalStorage } from '@vueuse/core'
import { randomUUID } from '@/utils/uuid'
import type { ChatMessage } from '@/store/chat/types'
import { ChatReadAloud, LiveSpeechReplies, SpeechTerminalError, speakingText, speechKey, speechText, type SpeechState, type SpeechEntry } from './chat-read-aloud'
import { chatWorkspaceVisibleKey } from './chat-workspace-visibility'
import { speechRenderComplete } from './speech-render-completion'
import { renderedSpeechText } from './speech-rendered-text'
import { beginSpeechTiming, type SpeechTiming } from './speech-timing'

/** Consecutive task failures of one reply before its automatic reading is
 * consumed like a stop: one transport or provider failure ends only that task
 * and later text reads through the next one; a reply whose tasks keep failing
 * stops retrying. */
export const speechFailureLimit = 2

/** Host lifecycle from the Harmony shell. EntryAbility.onBackground and
 * onForeground reach the Web layer as a `garnet:lifecycle` window event with
 * `detail.state` ('background' | 'foreground'), through the same
 * runJavaScript channel as the diagnostics resume event. Speech treats the
 * background like a hidden pane: parked at the spoken cursor, resumed on
 * return. A host without the shell never dispatches it and stays foreground. */
export const hostLifecycleEvent = 'garnet:lifecycle'
const hostForeground = shallowRef(true)
let hostListening = false
function listenHostLifecycle() {
  if (hostListening || typeof window === 'undefined') return
  hostListening = true
  window.addEventListener(hostLifecycleEvent, event => {
    const state = (event as CustomEvent<{ state?: unknown }>).detail?.state
    if (state === 'background') hostForeground.value = false
    else if (state === 'foreground') hostForeground.value = true
  })
}

export function useChatReadAloud(options: {
  botId: Ref<string | null | undefined>
  scope: Ref<string>
  /** Authorization gate: TTS configured, admitted route/anchor, no pending
   * contact navigation. Losing it stops and consumes, like an explicit stop. */
  enabled: Ref<boolean>
  /** Attention (pane active and visible): losing it parks speech at the spoken
   * cursor instead of consuming it — background, lock screen and hidden panes
   * resume where they left off. Absent means always attentive. */
  attention?: Ref<boolean>
  modelId?: Ref<string | undefined>
  nativeInput?: boolean
  runIdentity?: (message: ChatMessage) => string | undefined
  /** The message history load (first load, pagination). The chat-list refresh
   * is not a load window: it never gates reading or absorbs a live reply. */
  loading: Ref<boolean>
  /** Accepted for signature compatibility; typing never stops or gates speech. */
  draft?: Ref<string>
  messages: Ref<ChatMessage[]>
  messageElement?: (id: string) => Element | null
  bodyRoot?: () => Element | null
}) {
  const workspaceVisible = inject(chatWorkspaceVisibleKey, shallowRef(true))
  const enabled = computed(() => options.enabled.value && workspaceVisible.value)
  const state = shallowRef<SpeechState>({ key: '', status: 'idle' })
  const notice = shallowRef('')
  const generatedRuns = new Map<string, string>()
  const authToken = useLocalStorage('token', '')
  const activePrincipal = shallowRef(authToken.value)
  let replayRequest: AbortController | undefined
  let replayGeneration = 0
  // Page-memory capability cache. Invalidated on auth or model change and on
  // any stream-format mismatch, so a stale mime self-heals on the next task.
  let capabilityCache: { bot: string, model: string | undefined, principal: string, identity: string, mime: string } | undefined
  const replies = new LiveSpeechReplies()
  const timingOperations = new Map<string, SpeechTiming>()
  const failures = new Map<string, number>()
  let holdTimer: ReturnType<typeof setTimeout> | undefined
  let hostActive = true
  let observer: MutationObserver | undefined
  let observedRoot: Element | null = null
  const rendered = options.messageElement ? (message: ChatMessage) => renderedSpeechText(message, options.messageElement!(message.id)) : undefined
  const controller = new ChatReadAloud({
    ...(options.nativeInput ? { async openInput(entry: SpeechEntry, signal: AbortSignal) {
      const owner = entry.cacheKey ? JSON.parse(entry.cacheKey) as unknown[] : undefined
      const principal = localStorage.getItem('token') ?? authToken.value
      if (owner && (owner[0] !== principal || owner[1] !== options.botId.value || owner[2] !== options.scope.value)) throw new SpeechTerminalError('Playback owner changed')
      const bot = options.botId.value!
      const model = options.modelId?.value
      let mime = capabilityCache && capabilityCache.bot === bot && capabilityCache.model === model && capabilityCache.principal === principal ? capabilityCache.mime : undefined
      if (!mime) {
        const { data: capability, response: capabilityResponse } = await getBotsByBotIdTtsPlaybackConfig({ path: { bot_id: bot }, signal, throwOnError: false })
        // Every capability failure is explicit: 404, 401/403 and network/5xx
        // alike. There is no fresh-reply synthesis fallback any more.
        if (!capabilityResponse?.ok || !capability?.identity) throw new SpeechTerminalError('Playback capability is unavailable')
        mime = capability?.input_content_type
        // A configured non-MP3 mime is a deployment error, never a fallback.
        if (!mime || !/^audio\/(?:mpeg|mp3)(?:;|$)/u.test(mime)) throw new SpeechTerminalError('Playback input format changed')
        capabilityCache = { bot, model, principal, identity: capability.identity, mime }
      }
      if (signal.aborted) throw signal.reason
      if ((localStorage.getItem('token') ?? authToken.value) !== principal || bot !== options.botId.value || (owner && owner[2] !== options.scope.value)) throw new SpeechTerminalError('Playback owner changed')
      const id = randomUUID()
      const { data, response } = await postBotsByBotIdTtsPlaybackInput({ path: { bot_id: bot }, body: { id, sequence: 0, offset: 0, text: entry.text, final: false }, signal, parseAs: 'stream', throwOnError: true })
      const contentType = response.headers.get('Content-Type') ?? ''
      if (!(data instanceof ReadableStream) || contentType !== mime) {
        if (data instanceof ReadableStream) await data.cancel()
        capabilityCache = undefined
        throw new SpeechTerminalError('Playback input format changed')
      }
      activePrincipal.value = principal
      return {
        // One task through one native decoder; without MSE the same stream
        // aggregates into one Blob (prepareSpeechSource picks the branch).
        audio: { stream: data as ReadableStream<Uint8Array>, contentType, identity: response.headers.get('X-Speech-Playback-Identity') ?? '', sequential: true },
        async append(frame: import('./chat-read-aloud').SpeechInputFrame) {
          if (signal.aborted) throw signal.reason
          const current = localStorage.getItem('token') ?? authToken.value
          if (current !== principal || (owner && (owner[1] !== options.botId.value || owner[2] !== options.scope.value))) throw new SpeechTerminalError('Playback owner changed')
          await putBotsByBotIdTtsPlaybackInput({ path: { bot_id: bot }, body: { id, ...frame }, signal, throwOnError: true })
        },
      }
    } } : {}),
    createPlayer: () => new Audio(),
    createURL: blob => URL.createObjectURL(blob),
    revokeURL: url => URL.revokeObjectURL(url),
    onState: value => {
      state.value = value
      notice.value = value.status === 'error' ? 'chat.readAloud.failed' : ''
      const key = value.messageId ?? value.key
      if (value.status === 'playing') failures.delete(key)
      if (value.status === 'error') {
        // A deliberate abort (a task closed at a playback boundary, the host
        // parking) is not a provider or transport failure: it never counts
        // toward the consecutive limit and never consumes the reply.
        if (value.error instanceof DOMException && value.error.name === 'AbortError') return
        // A terminal failure, or a reply whose tasks keep failing, is consumed
        // like a stop: its queued deltas are discarded too. Any other single
        // failure ends only that task: the reply stays live, the deltas that
        // were queued but never sent continue through the next task, and the
        // failed task's own text is not retried.
        const count = (failures.get(key) ?? 0) + 1
        failures.set(key, count)
        if (value.error instanceof SpeechTerminalError || count >= speechFailureLimit) { replies.interrupt(options.messages.value); controller.discard() }
      }
    },
  })
  function clearHold() { if (holdTimer !== undefined) { clearTimeout(holdTimer); holdTimer = undefined } }
  function stop() {
    ++replayGeneration
    replayRequest?.abort(); replayRequest = undefined
    replies.interrupt(options.messages.value)
    controller.stop()
    timingOperations.clear()
    failures.clear()
    clearHold()
  }
  // A host losing attention (hidden, inactive, backgrounded) parks speech
  // instead of stopping it: the open task closes gracefully, the player pauses
  // in place and the live replies keep their spoken cursor. Regaining
  // attention resumes the parked audio and reads the completed sentences that
  // arrived meanwhile, in order. Losing authorization (enabled) still stops
  // and consumes.
  function suspend() {
    ++replayGeneration
    replayRequest?.abort(); replayRequest = undefined
    clearHold()
    controller.suspend()
  }
  function unsuspend() {
    if (!hostActive || !enabled.value || !attentive.value) return
    controller.unsuspend()
    collect()
  }
  listenHostLifecycle()
  // Pane attention (active and visible) and the shell's foreground state are
  // both required; losing either parks, regaining both resumes.
  const attentive = computed(() => options.attention?.value !== false && hostForeground.value)
  watch(options.scope, () => { stop(); replies.reset() }, { flush: 'sync' })
  if (options.modelId) watch(options.modelId, () => { capabilityCache = undefined; stop() }, { flush: 'sync' })
  watch(authToken, () => { capabilityCache = undefined; stop(); controller.clearCache(); generatedRuns.clear() }, { flush: 'sync' })
  watch(enabled, value => { if (!value) stop() }, { flush: 'sync' })
  watch(attentive, value => { if (value) unsuspend(); else suspend() }, { flush: 'sync' })
  watch(() => ({ messages: options.messages.value, enabled: enabled.value, loading: options.loading.value }), value => {
    for (const message of value.messages) if (message.role === 'assistant' && (message.runtimeRunId || options.runIdentity?.(message))) cacheKey(message, true)
    replies.observe(value.messages, value.enabled, value.loading)
  }, { deep: true, immediate: true, flush: 'sync' })
  function collect(flush = false) {
    if (enabled.value && !options.loading.value) {
      for (const message of options.messages.value) {
        if (message.role !== 'assistant' || !message.streaming) continue
        const key = message.id
        let operation = timingOperations.get(key)
        if (!operation) { operation = beginSpeechTiming('automatic'); if (operation) { if (timingOperations.size >= 32) timingOperations.delete(timingOperations.keys().next().value!); timingOperations.set(key, operation) } }
        if (message.messages.some(block => block.type === 'text' && block.content.length)) operation?.mark('text_observed')
      }
    }
    for (const reply of replies.update(options.messages.value, enabled.value, options.loading.value, flush, rendered)) {
      const message = options.messages.value.find(message => message.role === 'assistant' && (reply.messageId ? message.id === reply.messageId : speechKey(message) === reply.key))
      if (!message) continue
      const timing = timingOperations.get(reply.messageId ?? reply.key)
      controller.enqueue({ ...reply, cacheKey: cacheKey(message, true), ...(timing ? { timing } : {}) })
    }
    // A short completed sentence held for batching is released by time as
    // well as by text: schedule the update that lets it go.
    clearHold()
    const hold = replies.holdRemaining()
    if (hold !== undefined && enabled.value && !options.loading.value) holdTimer = setTimeout(() => { holdTimer = undefined; collect() }, hold)
    // A streaming reply keeps its one task open only while it is producing
    // text. When it moves on to reasoning or tools the task receives final:
    // the provider closes an input left idle (23 s) as a failure, which would
    // cut the audio and consume the rest of the reply. Later text in the same
    // reply is read through the next task. The controller also closes a task
    // itself inside that budget when the text simply stalls.
    controller.setLive(enabled.value && !options.loading.value ? options.messages.value.filter(message => message.role === 'assistant' && (message.streaming ? speakingText(message) : (replies.isObserved(message) && !renderComplete(message)))).map(message => message.id) : [])
  }
  function renderComplete(message: ChatMessage) {
    if (!options.nativeInput || !options.messageElement || message.role !== 'assistant') return true
    return speechRenderComplete(message, options.messageElement(message.id))
  }
  function observeBody() {
    const root = options.bodyRoot?.() ?? null
    if (observedRoot === root) return
    observer?.disconnect(); observedRoot = root
    if (!root) return
    observer ??= new MutationObserver(() => collect())
    observer.observe(root, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['class', 'style', 'hidden', 'data-markstream-mode', 'data-markstream-pending', 'data-speech-final'] })
  }
  watch(() => ({ messages: options.messages.value, enabled: enabled.value, loading: options.loading.value, scope: options.scope.value }), value => {
    if (value.messages.some(message => message.role === 'assistant' && (state.value.messageId ? message.id === state.value.messageId : speechKey(message) === state.value.key) && message.messages.some(block => block.type === 'error'))) { stop(); return }
    observeBody(); collect()
  }, { deep: true, immediate: true, flush: 'post' })
  function canResume(message: ChatMessage) {
    if ((localStorage.getItem('token') ?? authToken.value) !== activePrincipal.value) return false
    if (message.role !== 'assistant' || speechKey(message) !== state.value.key) return false
    const playback = status(message)
    return playback === 'blocked' || playback === 'paused'
  }
  function cacheKey(message: ChatMessage, generated = false) {
    // Read at use time as well as watching the shared auth ref: native hosts
    // can replace localStorage directly without a same-window storage event.
    const principal = localStorage.getItem('token') ?? authToken.value
    const slot = [principal, options.botId.value, options.scope.value, speechKey(message), message.id]
    const run = message.role === 'assistant' ? message.runtimeRunId || options.runIdentity?.(message) : undefined
    // Transcript reconciliation preserves the render id but omits runtimeRunId.
    // Bind the locally observed run to that exact row; sibling rows and known
    // later runs cannot inherit its audio. Text and server config also match.
    if (generated && run) generatedRuns.set(JSON.stringify(slot), run)
    return JSON.stringify([principal, options.botId.value, options.scope.value, options.modelId?.value, speechKey(message), message.id, run || generatedRuns.get(JSON.stringify(slot)) || ''])
  }
  function entry(message: ChatMessage) { return { key: speechKey(message), messageId: message.id, cacheKey: cacheKey(message), text: rendered ? rendered(message) : speechText(message) } }
  function menuAvailable(message: ChatMessage) { return enabled.value && message.role === 'assistant' && (canResume(message) || !!speechText(message)) }
  function canReplay(message: ChatMessage) { return enabled.value && (canResume(message) || !!speechText(message)) }
  function replayLabel(message: ChatMessage) { return canResume(message) ? 'chat.readAloud.continue' : 'chat.readAloud.replay' }
  // Clicking the reply that is being read stops it. A tap on another row, or
  // on a reply that has not started reading (expanding its process card,
  // dismissing a menu), leaves speech and the live reply alone. Tapping the
  // reasoning disclosure is an explicit reveal intent, never a stop.
  function stopReading(message: ChatMessage, event?: Event) {
    if (event?.target instanceof Element && event.target.closest('[data-reasoning-disclosure]')) return
    if (status(message) !== 'idle' || replies.isSpeaking(message)) stop()
  }
  async function replay(message: ChatMessage) {
    if (!enabled.value) return
    // The existing menu selection is the supported user activation. Resume the
    // same loaded source synchronously, before stop(), DOM work or any request.
    if (canResume(message)) { controller.resume(); return }
    if (message.streaming) {
      // A reply still being generated is read from its first sentence and then
      // follows the live reply through the same task, like an automatic read.
      if (!speechText(message)) return
      stop(); replies.follow(message); collect()
      return
    }
    const timing = beginSpeechTiming('manual')
    const cachedEntry = entry(message)
    if (!cachedEntry.text) return
    timing?.mark('text_observed')
    // Cached audio is never a precondition for reading aloud. Ready bytes replay
    // only after the read-only identity check; every other case synthesizes
    // through the same live path as an automatic reply.
    if (controller.replayAvailability(cachedEntry) !== 'ready') {
      stop()
      controller.enqueue({ ...cachedEntry, ...(timing ? { timing } : {}) })
      return
    }
    stop()
    const token = replayGeneration, scope = options.scope.value
    replayRequest = new AbortController()
    let replayed = false
    try {
      // Read-only current permission/config validation, never a TTS request.
      const { data } = await getBotsByBotIdTtsPlaybackConfig({ path: { bot_id: options.botId.value! }, signal: replayRequest.signal, throwOnError: true })
      if (token !== replayGeneration || scope !== options.scope.value || cachedEntry.cacheKey !== cacheKey(message) || cachedEntry.text !== entry(message).text || !enabled.value) return
      activePrincipal.value = localStorage.getItem('token') ?? authToken.value
      replayed = !!data?.identity && controller.replay({ ...cachedEntry, ...(timing ? { timing } : {}) }, data.identity)
    } catch {
      if (token !== replayGeneration) return
    } finally { if (token === replayGeneration) replayRequest = undefined }
    // Voice settings or text changed, or validation failed: re-synthesize now.
    if (token === replayGeneration && scope === options.scope.value && !replayed && enabled.value) controller.enqueue({ ...cachedEntry, ...(timing ? { timing } : {}) })
  }
  function status(message: ChatMessage) {
    const active = options.messages.value.find(item => item.role === 'assistant' && (state.value.messageId ? state.value.messageId === item.id : state.value.key === speechKey(item)))
    return message.role === 'assistant' && message.id === active?.id ? state.value.status : 'idle'
  }
  onDeactivated(() => { hostActive = false; suspend() })
  onMounted(() => { observeBody(); collect() })
  onActivated(() => { hostActive = true; void nextTick(() => { observeBody() }); unsuspend() })
  onBeforeUnmount(() => { observer?.disconnect(); stop(); controller.clearCache() })
  return { state, notice, status, stop, stopReading, replay, canReplay, menuAvailable, replayLabel, resume: () => { if (enabled.value) controller.resume() }, enabled }
}

