import type { ChatAssistantTurn, ChatMessage } from '@/store/chat/types'
import { visibleSpeechText } from './speech-visible-text'
import { streamingSpeechText } from './speech-streaming-text'
import { prepareSpeechSource, type SpeechAudioStream } from './speech-audio-stream'
import { beginSpeechTiming, type SpeechTiming } from './speech-timing'
import { completedSpeechPrefix } from './speech-sentence-boundary'
import { SpeechReplayCache } from './speech-replay-cache'

export type SpeechStatus = 'idle' | 'loading' | 'playing' | 'paused' | 'blocked' | 'error'
export interface SpeechState { key: string, messageId?: string, status: SpeechStatus, error?: unknown }
export interface SpeechEntry { key: string, messageId?: string, text: string, timing?: SpeechTiming, cacheKey?: string }
interface SpeechJob extends SpeechEntry { sourceText?: string, audio?: Blob | SpeechAudioStream }
export interface SpeechPlayer {
  src: string
  readonly currentTime?: number
  readonly buffered?: TimeRanges
  play(): Promise<void>
  pause(): void
  load(): void
  addEventListener(type: string, listener: EventListener): void
  removeEventListener(type: string, listener: EventListener): void
}
export interface SpeechInputFrame { sequence: number, offset: number, text: string, final: boolean }
export interface SpeechInputSession {
  audio: SpeechAudioStream
  append(frame: SpeechInputFrame): Promise<void>
}
export interface SpeechDependencies {
  openInput?(entry: SpeechEntry, signal: AbortSignal): Promise<SpeechInputSession>
  createPlayer(): SpeechPlayer
  createURL(blob: Blob | MediaSource): string
  revokeURL(url: string): void
  onState(state: SpeechState): void
  onCacheChange?(): void
}

/** The native input protocol's per-frame code-point ceiling is the only frame
 * split. One task keeps a single synthesis context across frames; boundaries
 * are transport only and never a fixed-text chunking strategy. */
export const speechInputFrameLimit = 20000
/** The provider closes a task whose consecutive text frames are more than
 * 23 s apart (Qwen/CosyVoice continue-task contract), and the server rejects
 * an empty non-final frame, so no keepalive exists. The client closes an idle
 * task itself inside that budget, leaving margin for the final frame's round
 * trip; the audio already requested then plays out, and the next text of the
 * same reply opens the next task after it has ended. A tool step that lasts
 * longer than the provider limit no longer cuts the audio and never consumes
 * the rest of the reply. */
export const speechInputIdleLimit = 15000
/** After the first sentence of a reply, which always ships alone for the
 * fastest first audio, completed sentences are batched until they reach a
 * minimum span, so list items, one-word lines and other tiny sentences are
 * not each a synthesis unit of their own. 20 code points follows LiveKit
 * agents' SentenceTokenizer(min_sentence_len=20). A held span is released by
 * the next text that lifts it over the minimum, by any flush (tool step,
 * settled frame, manual read) or after speechShortSentenceHold milliseconds,
 * so a stalled reply never leaves a completed sentence waiting. */
export const speechMinSentenceSpan = 20
export const speechShortSentenceHold = 1500
/** A failure later text of the same reply cannot recover from: the playback
 * owner, the capability or the stream format changed. Any other failure (the
 * provider input gap, transport, media) ends only the current task: the reply
 * stays live and its later text reads through the next task. The failed
 * task's own text is never retried. */
export class SpeechTerminalError extends Error {}
export function speechInputFrames(text: string, limit = speechInputFrameLimit): string[] {
  const points = Array.from(text)
  const frames: string[] = []
  for (let start = 0; start < points.length; start += limit) frames.push(points.slice(start, start + limit).join(''))
  return frames
}

export function speechKey(message: ChatMessage): string {
  return message.turnId || message.serverId || message.id
}

/** A construct the streaming parser reclassifies after it was spoken (a
 * released long bracketed label closing into a link, a reference definition
 * landing at the end) breaks the exact-prefix cursor. The spoken cursor then
 * rolls back to the longest common prefix and rereads from that boundary,
 * whatever the divergence: a bounded duplicate of the reclassified span is
 * the acceptable cost of never leaving the rest of the reply silent and
 * consumed. The boundary is measured in code points, like every other speech
 * length, so it always lands between characters. A replaced run never reaches
 * this comparison, its revision starts a fresh cursor. */
export function commonSpeechPrefix(text: string, prior: string): string {
  const left = Array.from(text), right = Array.from(prior)
  const limit = Math.min(left.length, right.length)
  let end = 0
  while (end < limit && left[end] === right[end]) end++
  return left.slice(0, end).join('')
}

/** The first conversation_ack status line of a reply, '' when there is none.
 * Shared by the frame-text assembly and the spoken cursor: both must agree on
 * which block carries the ephemeral ack (the display layer clears the ack row
 * once body text exists, the projection drops the whole status block when the
 * run settles, and neither changes this single collection point). */
function conversationAckOf(message: ChatMessage): string {
  if (message.role !== 'assistant') return ''
  for (const block of message.messages) {
    if (block.type === 'status' && block.name === 'conversation_ack' && block.args?.text) return block.args.text
  }
  return ''
}

export function speechText(message: ChatMessage): string {
  if (message.role !== 'assistant') return ''
  // Explicit audio/voice output remains an attachment; do not read its accompanying
  // caption a second time. Never synthesize tool output, errors or reasoning.
  if (message.messages.some(block => block.type === 'attachments' && block.attachments.some(att =>
    att.type === 'audio' || att.type === 'voice' || att.mime?.startsWith('audio/'),
  ))) return ''
  // A fast acknowledgement (ack) rides in a conversation_ack status block and
  // reads like reply text ahead of the body, through the same task and framing
  // contract (the server-side ack pipeline is not deployed yet, so no ack
  // reaches a client today). While the run is active the runtime projection
  // appends the status block after every content block regardless of when it
  // arrived, so the ack is collected from any position and always spoken
  // ahead of the body: cursor continuity then never depends on where the
  // status block sits, and an ack landing in the same frame as the first body
  // text still reads. The terminal frame drops the status block entirely
  // (runtime-projection keeps runtime status only for active runs), so the
  // frame text of a settled reply carries the body alone; LiveSpeechReplies
  // treats the ack prefix as ephemeral for exactly that reason. The line is
  // server-authored speakable text, not markdown body.
  const parts: string[] = []
  for (const block of message.messages) {
    if (block.type === 'text') parts.push(message.streaming ? streamingSpeechText(block.content) : visibleSpeechText(block.content))
  }
  const ack = conversationAckOf(message)
  if (ack) parts.unshift(ack)
  return parts.join('\n\n').trim()
}

/** A streaming reply is speaking while its newest content block is reply text.
 * Status blocks are skipped: the ack line reads through the reply's task like
 * text, and other runtime status never carries speech. Once the newest
 * non-status block is reasoning, a tool or other output, the text so far is
 * complete; an ack-only reply has no open text and finishes its own short task. */
export function speakingText(message: ChatMessage): boolean {
  return message.role === 'assistant' && message.messages.findLast(block => block.type !== 'status')?.type === 'text'
}

/** Reply eligibility. Existing rows become eligible through state transitions:
 * R1 streaming true→false and R2 a revision change that completes; never having
 * observed a streaming frame no longer silences a completed reply. New rows are
 * judged by position: R3 a tail append is eligible, B-γ a prepend/mid-insert is
 * absorbed as baseline (pagination can only prepend, so history never reads).
 * B-α scope entry/reset and B-β history-load windows absorb the rows they see,
 * except a reply that is still streaming: it arrives through the live stream
 * of an active session and is never baseline, whatever window or position it
 * lands in. Only the message history load (loadingMessages) is a load window;
 * the chat-list refresh never gates reading. Baseline only exempts the row's
 * state at absorption; later R1/R2 transitions still read. Interruption (an
 * explicit stop) consumes the live reply as well as the queue; a disabled
 * host only parks it, keeping the spoken cursor for the next enabled update.
 * Reply text is read from its first completed sentence; questions and options
 * written in reply text read like any other sentence. A fast acknowledgement
 * (ack) reads through the same incremental task contract; the server-side ack
 * pipeline is not deployed yet, so no ack reaches a client today. */
interface SpokenCursor { ack: string, body: string }

export class LiveSpeechReplies {
  private live = new Map<string, string>()
  private spoken = new Map<string, SpokenCursor>()
  private consumed = new Set<string>()
  private interruptedRuns = new Set<string>()
  private interruptedInvocations = new Set<string>()
  private known = new Map<string, { baseline: boolean, revision: string, streaming: boolean }>()
  private held = new Map<string, number>()
  private initialized = false
  private wasLoading = false
  private minSpan: number
  private holdMs: number
  private now: () => number
  constructor(options: { minSpan?: number, holdMs?: number, now?: () => number } = {}) {
    this.minSpan = options.minSpan ?? speechMinSentenceSpan
    this.holdMs = options.holdMs ?? speechShortSentenceHold
    this.now = options.now ?? (() => Date.now())
  }
  reset() { this.live.clear(); this.spoken.clear(); this.consumed.clear(); this.interruptedRuns.clear(); this.interruptedInvocations.clear(); this.known.clear(); this.held.clear(); this.initialized = false; this.wasLoading = false }
  isObserved(message: ChatMessage) { return this.live.has(message.id) }
  /** Milliseconds until the oldest held short span must be released, or
   * undefined when nothing is held. The host schedules the next update. */
  holdRemaining(): number | undefined {
    let soonest: number | undefined
    for (const since of this.held.values()) {
      const left = Math.max(0, since + this.holdMs - this.now())
      soonest = soonest === undefined ? left : Math.min(soonest, left)
    }
    return soonest
  }
  /** A live reply that has started speaking, including between its tasks. */
  isSpeaking(message: ChatMessage) {
    const observed = this.live.get(message.id)
    const spoken = observed && this.spoken.get(observed)
    return !!observed && !!(spoken && (spoken.ack || spoken.body))
  }
  /** The read-aloud entry on a reply that is still being generated: read it
   * from its first sentence and keep following it like a live reply, even if
   * an earlier stop consumed its automatic reading. */
  follow(message: ChatMessage) {
    if (message.role !== 'assistant') return
    const revision = this.revisionOf(message)
    this.consumed.delete(revision)
    if (message.runtimeRunId) this.interruptedRuns.delete(message.runtimeRunId)
    if (message.invocationId) this.interruptedInvocations.delete(message.invocationId)
    this.spoken.delete(revision)
    this.held.delete(revision)
    this.register(message)
  }
  private revisionOf(message: ChatAssistantTurn) { return message.runtimeRunId ? `${message.id}:${message.runtimeRunId}` : message.id }
  private intercepts(message: ChatAssistantTurn) {
    const revision = this.revisionOf(message)
    return this.consumed.has(revision)
      || (!!message.runtimeRunId && this.interruptedRuns.has(message.runtimeRunId))
      || (!!message.invocationId && this.interruptedInvocations.has(message.invocationId))
  }
  private absorb(message: ChatAssistantTurn) {
    this.known.set(message.id, { baseline: true, revision: this.revisionOf(message), streaming: !!message.streaming })
  }
  private register(message: ChatAssistantTurn) {
    const revision = this.revisionOf(message)
    this.known.set(message.id, { baseline: false, revision, streaming: !!message.streaming })
    this.live.set(message.id, revision)
  }
  // Capture eligibility in the reactive update, before Vue batches a fast turn
  // into its final render. Reading visible text still waits for the DOM watcher.
  observe(messages: ChatMessage[], enabled: boolean, loading: boolean) {
    if (enabled) this.track(messages, loading)
  }
  interrupt(messages: ChatMessage[]) {
    for (const message of messages) {
      const key = message.id
      this.consumed.add(message.role === 'assistant' && message.runtimeRunId ? `${key}:${message.runtimeRunId}` : key)
      if (message.role === 'assistant' && message.streaming) {
        if (message.runtimeRunId) this.interruptedRuns.add(message.runtimeRunId)
        if (message.invocationId) this.interruptedInvocations.add(message.invocationId)
      }
    }
    // A stopped reply never regains eligibility by completing afterwards: drop
    // every pending completion transition, not just the rows in this array.
    for (const row of this.known.values()) row.streaming = false
    this.live.clear()
    this.spoken.clear()
    this.held.clear()
  }
  private track(messages: ChatMessage[], loading: boolean) {
    if (!this.initialized) {
      // B-α: scope entry or reset absorbs the rows already present. A reply
      // still streaming is live, not history: it reads from its first
      // completed sentence like any other live reply.
      this.initialized = true
      for (const message of messages) if (message.role === 'assistant') { if (message.streaming) this.register(message); else this.absorb(message) }
      this.wasLoading = loading
      return
    }
    // B-β: rows that appear inside a history-load window (or its landing tick)
    // are baseline. Array reconciliation preserves ids, so a replacement array
    // never re-reads already-known rows.
    const absorbNew = loading || this.wasLoading
    const order = new Map<string, number>()
    const assistants = new Map<string, ChatAssistantTurn>()
    messages.forEach((row, index) => { if (row.role === 'assistant') { order.set(row.id, index); assistants.set(row.id, row) } })
    for (const [id, index] of order) {
      const message = assistants.get(id)!
      if (this.intercepts(message)) { if (!this.known.has(id)) this.absorb(message); continue }
      const known = this.known.get(id)
      if (!known) {
        // R3 vs B-γ: a row after every known row present in this array is a
        // tail append; anything before or between known rows was inserted.
        // A streaming row arrived through the live stream of the active
        // session: it is never baseline, whatever window or position it
        // landed in (history can only be settled rows).
        let tailAppend = true
        for (const [other, otherIndex] of order) if (this.known.has(other) && otherIndex > index) { tailAppend = false; break }
        if (!message.streaming && (absorbNew || !tailAppend)) { this.absorb(message); continue }
        this.register(message)
        continue
      }
      // A settled projection omits runtimeRunId; that is reconciliation, not a
      // revision change. Only an explicitly different run replaces the row.
      if (message.runtimeRunId && known.revision !== this.revisionOf(message)) {
        // R2: retry/steer replaces the run on an existing row. The new run
        // reads on completion; interrupted runs never come back to life. The
        // old run's cursor and any short span it was holding go with it.
        this.spoken.delete(known.revision)
        this.held.delete(known.revision)
        known.revision = this.revisionOf(message)
        known.streaming = !!message.streaming
        this.live.delete(id)
        if (!loading && !message.streaming) this.live.set(id, known.revision)
        continue
      }
      if (known.streaming && !message.streaming) {
        // R1: a completion transition on an existing row, observed or not.
        known.streaming = false
        if (!loading && !this.live.has(id)) this.live.set(id, known.revision)
      } else known.streaming = !!message.streaming
    }
    this.wasLoading = loading
    // A held short span belongs to a row of this array: a row that was
    // dropped (an abandoned turn replaced wholesale) or re-run takes its hold
    // with it, so holdRemaining() never reports a stale, already-expired hold
    // that would keep the host rescheduling for nothing.
    if (this.held.size) {
      const valid = new Set<string>()
      for (const [id, message] of assistants) {
        const observed = this.live.get(id)
        if (observed) valid.add(observed)
        valid.add(this.revisionOf(message))
      }
      for (const key of Array.from(this.held.keys())) if (!valid.has(key)) this.held.delete(key)
    }
  }
  update(messages: ChatMessage[], enabled: boolean, loading: boolean, flush = false, rendered?: (message: ChatMessage) => string): SpeechEntry[] {
    if (!enabled) { this.interrupt(messages); return [] }
    this.track(messages, loading)
    if (loading) return []
    const result: SpeechEntry[] = []
    for (const message of messages) {
      if (message.role !== 'assistant') continue
      const key = message.id
      const revision = this.revisionOf(message)
      if (this.intercepts(message)) continue
      const observed = this.live.get(key)
      // Eligibility is decided in track(); only live-registered rows parse and
      // read text. Absorbed and baseline rows stay silent until a transition.
      if (!observed) continue
      const text = rendered ? rendered(message) : speechText(message)
      if (message.messages.some(block => block.type === 'error')) { this.consumed.add(revision); continue }
      if (message.streaming || !message.runtimeRunId || observed === revision) {
        // Settled history omits runtimeRunId; retain the observed run for both
        // cursor reads and commits. An explicit new run keeps its own revision.
        const cursorRevision = observed && !message.runtimeRunId ? observed : revision
        const prior = this.spoken.get(cursorRevision) ?? { ack: '', body: '' }
        // The ack prefix of the frame text is ephemeral: the runtime
        // projection keeps the conversation_ack status block only while the
        // run is active, so the terminal frame that settles the reply carries
        // the body alone. The spoken cursor therefore tracks the body on its
        // own — the ack is peeled off the frame text (and spoken once, when
        // first seen) but its disappearance never rolls the body cursor back
        // and a late ack never replays body text that already read.
        let bodyText = text
        let frameAck = ''
        let pendingAck = ''
        if (!rendered) {
          frameAck = conversationAckOf(message).trim()
          if (frameAck && text.startsWith(frameAck)) {
            const rest = text.slice(frameAck.length)
            bodyText = rest.startsWith('\n\n') ? rest.slice(2).replace(/^\s+/u, '') : ''
            if (prior.ack !== frameAck) pendingAck = frameAck
          } else frameAck = ''
        }
        // The exact prefix continues the one cursor without resending
        // anything. A construct already spoken can still be reclassified by
        // the streaming parser (for example a released long bracketed label
        // closing into a link, or a reference definition landing at the
        // end); the exact-prefix cursor cannot continue then, and refusing
        // the continuation would suppress every later delta. Roll the cursor
        // back to the common prefix and reread from that boundary, on
        // streaming and settled frames alike: a bounded duplicate of the
        // reclassified span is the acceptable cost.
        const kept = bodyText.startsWith(prior.body) ? prior.body : commonSpeechPrefix(bodyText, prior.body)
        const tail = bodyText.slice(kept.length)
        let end = tail.length
        // Only completed sentences stream; the server splits synthesis
        // itself. There is no fixed-rune forced split any more. A reply that
        // moved on from its text (a tool or reasoning step) has completed
        // that text, and a settled frame is the reply's last: nothing follows
        // either that could resolve the closing sentence, so the tail flushes
        // whole instead of being held behind the completed-sentence boundary.
        const holding = message.streaming && !flush && speakingText(message)
        // Holding means the row is still streaming: ask the boundary for
        // streaming commits so each completed sentence ships in the tick it
        // completes (E2 first-sentence read; short continue-task gaps).
        if (holding) end = completedSpeechPrefix(tail, true)
        const spokenBody = tail.slice(0, end)
        if (holding && this.holdsShort(cursorRevision, prior, pendingAck, spokenBody)) continue
        const delta = pendingAck ? (spokenBody ? pendingAck + '\n\n' + spokenBody : pendingAck) : spokenBody
        if (delta.trim()) {
          result.push({ key: speechKey(message), messageId: message.id, text: delta })
          this.spoken.set(cursorRevision, { ack: frameAck || prior.ack, body: kept + spokenBody })
          this.held.delete(cursorRevision)
        }
      }
      // A final message can precede typewriter, math and diagram DOM updates.
      // Retain only already-observed live replies so those later visible tails
      // can be collected. Stop/scope/permission changes still consume the run.
      if (message.streaming || rendered) continue
      this.live.delete(key)
      this.consumed.add(revision)
      if (observed) this.consumed.add(observed)
      if (!observed || (message.runtimeRunId && observed !== revision)) continue
      this.spoken.delete(revision)
      if (observed) this.spoken.delete(observed)
    }
    return result
  }
  /** Short-sentence batching after the first sentence of a reply: a completed
   * span under the minimum waits for more text, unless it has already waited
   * the hold limit. The first body sentence (with or without an ack ahead of
   * it) always ships at once. */
  private holdsShort(cursor: string, prior: SpokenCursor, pendingAck: string, spokenBody: string): boolean {
    if (!spokenBody.trim() || !prior.body || pendingAck) return false
    if (Array.from(spokenBody).length >= this.minSpan) return false
    const since = this.held.get(cursor)
    if (since !== undefined && this.now() - since >= this.holdMs) return false
    if (since === undefined) this.held.set(cursor, this.now())
    return true
  }
}

/** One player, one in-flight synthesis request, one generation. No retry of a
 * failed/uncertain synthesis. Late promises and media events cannot restart it. */
export class ChatReadAloud {
  private generation = 0
  private queue: SpeechJob[] = []
  private cache: SpeechReplayCache
  private abort?: AbortController
  private player?: SpeechPlayer
  private url = ''
  private detach?: () => void
  private disposeStream?: () => void
  private timing?: SpeechTiming
  private liveKeys = new Set<string>()
  private wake?: () => void
  private currentMessageId?: string
  private currentJob?: SpeechJob
  private taskClosing = false
  private suspended = false
  private state: SpeechState = { key: '', status: 'idle' }
  private deps: SpeechDependencies
  constructor(deps: SpeechDependencies) { this.deps = deps; this.cache = new SpeechReplayCache(deps.onCacheChange) }

  private publish(key: string, status: SpeechStatus, error?: unknown) {
    this.state = { key, status, error, ...(this.currentMessageId ? { messageId: this.currentMessageId } : {}) }
    this.deps.onState(this.state)
  }
  private release() {
    this.disposeStream?.(); this.disposeStream = undefined
    this.detach?.(); this.detach = undefined
    if (this.player) { this.player.pause(); this.player.src = ''; this.player.load() }
    if (this.url) { this.deps.revokeURL(this.url); this.url = '' }
  }
  stop() {
    this.timing?.mark('interrupted'); this.timing = undefined
    ++this.generation
    this.queue = []
    this.abort?.abort(); this.abort = undefined
    this.liveKeys.clear(); this.wake?.(); this.wake = undefined
    this.release()
    this.currentJob = undefined
    this.currentMessageId = undefined
    this.publish('', 'idle')
  }
  /** The host is hidden or inactive: park playback without consuming anything.
   * The open task receives final so the provider finishes what was already
   * sent instead of failing on the input gap, the player pauses in place
   * keeping its loaded source, and queued or later deltas wait for
   * unsuspend(). Nothing is aborted, so showing the host again resumes the
   * same audio without a new synthesis. */
  suspend() {
    if (this.suspended) return
    this.suspended = true
    this.liveKeys.clear(); this.wake?.()
    if (this.player && this.url) {
      this.player.pause()
      if (this.state.status === 'playing' || this.state.status === 'loading' || this.state.status === 'paused') this.publish(this.state.key, 'paused')
    }
  }
  unsuspend() {
    if (!this.suspended) return
    this.suspended = false
    if (this.player && this.url && (this.state.status === 'paused' || this.state.status === 'blocked')) { this.tryPlay(this.generation); return }
    if ((this.state.status === 'idle' || this.state.status === 'error') && this.queue.length) void this.next()
  }
  enqueue(entry: SpeechEntry) {
    if (!entry.text.trim()) { this.wake?.(); return }
    const operation = entry.timing ?? beginSpeechTiming('direct')
    const timing = operation?.fork(); timing?.mark('text_chunk_ready')
    // One whole-text job: the single native task frames it at the protocol
    // limit; the server segments sentences inside one synthesis context.
    this.queue.push({ key: entry.key, messageId: entry.messageId, cacheKey: entry.cacheKey, text: entry.text, timing })
    this.wake?.()
    if (this.state.status === 'idle' || this.state.status === 'error') void this.next()
  }
  setLive(keys: Iterable<string>) { this.liveKeys = new Set(keys); this.wake?.() }
  clearCache() { this.cache.clear() }
  replayAvailability(entry: SpeechEntry) { return this.cache.status(entry.cacheKey ?? entry.key, entry.text) }
  replay(entry: SpeechEntry, identity: string): boolean {
    const parts = this.cache.read(entry.cacheKey ?? entry.key, entry.text, identity)
    if (!parts) return false
    this.stop()
    // MSE can replay the same encoded MP3 bytes on its one native clock. Other
    // formats retain separate, already-generated native files; no re-encoding.
    if (/^audio\/(?:mpeg|mp3)(?:;|$)/u.test(parts[0]!.type) && typeof MediaSource !== 'undefined' && MediaSource.isTypeSupported(parts[0]!.type)) {
      const buffers = parts.map(part => part.stream())
      let reader = buffers.shift()!.getReader()
      let canceled = false
      const stream = new ReadableStream<Uint8Array>({ async pull(output) {
        for (;;) {
          const next = await reader.read()
          if (canceled) return
          if (!next.done) { output.enqueue(next.value); return }
          reader.releaseLock(); const nextStream = buffers.shift()
          if (!nextStream) { output.close(); return }
          reader = nextStream.getReader()
        }
      }, cancel(reason) { canceled = true; buffers.length = 0; void reader.cancel(reason).catch(() => {}); reader.releaseLock() } }, { highWaterMark: 0 })
      this.queue.push({ ...entry, audio: { stream, contentType: parts[0]!.type, sequential: true } })
    } else this.queue.push(...parts.map(audio => ({ ...entry, audio })))
    void this.next(); return true
  }
  resume() {
    // Called directly by the user's button gesture. Reuse the already loaded
    // audio; do not await a network request before calling play().
    if (this.player && (this.state.status === 'blocked' || this.state.status === 'paused')) {
      this.tryPlay(this.generation)
    }
  }
  /** Drop every queued delta without touching the current state: the host
   * decided a failure is terminal (or the reply keeps failing), so nothing
   * of that reply continues through another task. */
  discard() { this.queue = [] }
  private fail(token: number, error: unknown) {
    if (token !== this.generation) return
    this.timing?.mark('error')
    ++this.generation
    this.abort?.abort(); this.abort = undefined
    this.wake?.(); this.wake = undefined
    this.release()
    // The spoken cursor advanced when the delta was produced, long before
    // this task failed; without a rollback the next burst continues after
    // text whose audio never played (E2c: the middle of a long reply drops
    // and the tail reads as if it jumped). The failed task's fed text is
    // re-queued whole: a bounded duplicate of the part the listener may
    // already have heard is the accepted cost, the same trade the
    // reclassification rollback makes. A deliberate abort (stop, host
    // parking) is not a failure and never reschedules.
    const failed = this.currentJob
    this.currentJob = undefined
    this.taskClosing = false
    const aborted = error instanceof DOMException && error.name === 'AbortError'
    if (!aborted && failed && (failed.sourceText ?? failed.text).trim()) {
      this.timing?.mark('task_failed', { codepoints: Array.from(failed.sourceText ?? failed.text).length, cause: 'task' })
      this.queue.unshift({ key: failed.key, messageId: failed.messageId, cacheKey: failed.cacheKey, text: failed.sourceText ?? failed.text })
    }
    // Only the failed task is lost: its own text is never retried. Deltas that
    // were queued but never sent to any task (they arrived while the task was
    // still opening, or while its audio played) keep their place and continue
    // through the next task, in order and without repeating anything, unless
    // the host discards them from the error notification.
    this.publish(this.state.key, 'error', error)
    if (this.queue.length) void this.next()
  }
  private tryPlay(token: number) {
    // A suspended host keeps the loaded source parked; unsuspend() plays it.
    if (this.suspended) { this.publish(this.state.key, 'paused'); return }
    try {
      this.timing?.mark('native_play_call')
      void this.player!.play().catch(error => {
        if (token !== this.generation) return
        if (this.suspended) { this.publish(this.state.key, 'paused'); return }
        if (error && typeof error === 'object' && error.name === 'NotAllowedError') {
          this.timing?.mark('blocked')
          this.publish(this.state.key, 'blocked')
        } else this.fail(token, error)
      })
    } catch (error) { this.fail(token, error) }
  }
  /** One native decoder/clock. Wakes when a queued delta of the same reply can
   * extend the one task, when the reply is no longer live and must finish, or
   * (resolving true) when the input has been idle for the client budget. */
  private waitInput(signal: AbortSignal, ready: () => boolean, idleMs: number) {
    return new Promise<boolean>((resolve, reject) => {
      let timer: ReturnType<typeof setTimeout> | undefined
      const finish = (idle: boolean) => {
        if (timer !== undefined) { clearTimeout(timer); timer = undefined }
        signal.removeEventListener('abort', check); this.wake = undefined
        if (signal.aborted) reject(signal.reason); else resolve(idle)
      }
      const check = () => { if (!signal.aborted && !ready()) return; finish(false) }
      this.wake = check; signal.addEventListener('abort', check, { once: true })
      if (signal.aborted || ready()) { check(); return }
      timer = setTimeout(() => finish(true), idleMs)
    })
  }
  private async feedInput(session: SpeechInputSession, entry: SpeechJob, signal: AbortSignal, pending: string[]) {
    let sequence = 1, offset = Array.from(entry.sourceText ?? entry.text).length
    const send = async (text: string) => {
      await session.append({ sequence, offset, text, final: false })
      entry.timing?.mark('input_frame_sent', { sequence, offset, codepoints: Array.from(text).length })
      entry.sourceText = (entry.sourceText ?? '') + text
      offset += Array.from(text).length; sequence++
    }
    for (const text of pending) await send(text)
    for (;;) {
      const idle = await this.waitInput(signal, () => this.queue.length > 0 || this.taskClosing || !this.liveKeys.has(entry.messageId ?? entry.key), speechInputIdleLimit)
      const next = this.queue[0]
      if (idle || !next || next.key !== entry.key || next.messageId !== entry.messageId || next.cacheKey !== entry.cacheKey) {
        await session.append({ sequence, offset, text: '', final: true }); entry.timing?.mark('input_frame_sent', { sequence, offset, final: true }); return
      }
      this.queue.shift()
      for (const text of speechInputFrames(next.sourceText ?? next.text)) await send(text)
    }
  }
  private async request(entry: SpeechJob, signal: AbortSignal) {
    const token = this.generation
    if (!this.deps.openInput) throw new SpeechTerminalError('Native playback input is unavailable')
    const frames = speechInputFrames(entry.sourceText ?? entry.text)
    const session = await this.deps.openInput({ ...entry, text: frames[0] ?? '' }, signal)
    if (signal.aborted) {
      void session.audio.stream.cancel().catch(() => {})
      throw signal.reason
    }
    entry.sourceText = frames[0] ?? ''
    void this.feedInput(session, entry, signal, frames.slice(1)).catch(error => this.fail(token, error))
    return this.cache.capture(entry.cacheKey ?? entry.key, () => entry.sourceText ?? entry.text, { ...session.audio, incrementalInput: true }, signal)
  }
  private async next() {
    // A suspended host never opens a task: the queue waits for unsuspend().
    if (this.suspended) { this.timing = undefined; this.currentMessageId = undefined; this.publish('', 'idle'); return }
    const entry = this.queue.shift()
    if (!entry) { this.timing = undefined; this.currentMessageId = undefined; this.publish('', 'idle'); return }
    const token = ++this.generation
    this.currentJob = entry
    this.taskClosing = false
    this.timing = entry.timing
    this.currentMessageId = entry.messageId
    this.abort = new AbortController()
    this.publish(entry.key, 'loading')
    try {
      const signal = this.abort.signal
      if (!entry.audio) entry.timing?.mark('request_start')
      const audio = entry.audio ?? await this.request(entry, signal)
      if (token !== this.generation) {
        if (!(audio instanceof Blob)) void audio.stream.cancel().catch(() => {})
        return
      }
      this.release()
      this.player ??= this.deps.createPlayer()
      if (audio instanceof Blob) this.url = this.deps.createURL(audio)
      else {
        // One stream source: MSE single SourceBuffer sequence on this browser,
        // or the same single task aggregated into one Blob when MSE is absent.
        const stream = await prepareSpeechSource(audio, signal, source => this.deps.createURL(source), entry.timing)
        if (token !== this.generation) {
          stream.dispose(); this.deps.revokeURL(stream.url)
          void stream.done.catch(() => {})
          return
        }
        this.url = stream.url
        this.disposeStream = stream.dispose
        void stream.done.catch(error => this.fail(token, error))
      }
      this.player.src = this.url
      const handlers: Record<string, EventListener> = {
        playing: () => { if (token === this.generation) { entry.timing?.mark('native_playing'); this.publish(entry.key, 'playing') } },
        pause: () => { if (token === this.generation) this.publish(entry.key, 'paused') },
        waiting: () => { if (token === this.generation) this.publish(entry.key, 'loading') },
        ended: () => {
          if (token !== this.generation) return
          entry.timing?.mark('native_ended')
          // A premature ended (audio shorter than the input still feeding
          // it, or a truncated body) must not abort an in-flight append:
          // the frame completes into this task instead of being swallowed
          // and no AbortError is manufactured into a task failure.
          this.taskClosing = true; this.wake?.(); this.abort = undefined
          this.release()
          void this.next()
        },
        error: () => this.fail(token, new Error('Audio playback failed')),
      }
      for (const [type, handler] of Object.entries(handlers)) this.player.addEventListener(type, handler)
      this.detach = () => {
        for (const [type, handler] of Object.entries(handlers)) this.player?.removeEventListener(type, handler)
      }
      this.tryPlay(token)
    } catch (error) { this.fail(token, error) }
  }
}

import { describe, expect, it, vi } from 'vitest'
import type { ChatAssistantTurn } from '@/store/chat/types'
import { ChatReadAloud, LiveSpeechReplies, speechInputFrames, speechKey, speechText, type SpeechInputFrame, type SpeechInputSession, type SpeechState } from './chat-read-aloud'

class Player extends EventTarget {
  src = ''
  play = vi.fn(async () => {})
  pause = vi.fn()
  load = vi.fn()
  emit(type: string) { this.dispatchEvent(new Event(type)) }
}
const tick = async () => { for (let i = 0; i < 20; i++) await Promise.resolve() }
function fixture() {
  const player = new Player(), states: SpeechState[] = [], frames: SpeechInputFrame[] = []
  const revokeURL = vi.fn(), createURL = vi.fn(() => 'blob:synthetic')
  const openInput = vi.fn(async (_entry: { text: string }, _signal: AbortSignal): Promise<SpeechInputSession> => ({
    audio: { stream: new ReadableStream<Uint8Array>({ start(c) { c.enqueue(new Uint8Array([1])); c.close() } }), contentType: 'audio/wav', identity: 'configured' },
    append: vi.fn(async (frame: SpeechInputFrame) => { frames.push(frame) }),
  }))
  const speech = new ChatReadAloud({ openInput, createPlayer: () => player, createURL, revokeURL, onState: state => states.push(state) })
  return { speech, player, states, frames, revokeURL, createURL, openInput, latest: () => states.at(-1) }
}
function reply(id: string, streaming = false, text = '你好'): ChatAssistantTurn {
  return { id, turnId: `turn:${id}`, role: 'assistant', streaming, timestamp: '', messages: [{ id: 1, type: 'text', content: text }] }
}

describe('chat read aloud media lifecycle', () => {
  it('reads in order, highlights only actual playing, pauses and ends cleanly', async () => {
    const f = fixture()
    f.speech.enqueue({ key: 'a', text: 'one' }); f.speech.enqueue({ key: 'b', text: 'two' })
    await tick()
    expect(f.latest()).toMatchObject({ key: 'a', status: 'loading' })
    f.player.emit('playing'); expect(f.latest()).toMatchObject({ key: 'a', status: 'playing' })
    f.player.emit('pause'); expect(f.latest()?.status).toBe('paused')
    f.speech.resume(); expect(f.player.play).toHaveBeenCalledTimes(2)
    f.player.emit('playing'); f.player.emit('waiting'); expect(f.latest()?.status).toBe('loading')
    f.player.emit('playing'); f.player.emit('ended'); await tick()
    expect(f.latest()).toMatchObject({ key: 'b', status: 'loading' })
    f.player.emit('playing'); expect(f.latest()).toMatchObject({ key: 'b', status: 'playing' })
    f.player.emit('ended'); expect(f.latest()?.status).toBe('idle')
    expect(f.openInput.mock.calls.map(call => call[0]!.text)).toEqual(['one', 'two'])
    expect(f.revokeURL).toHaveBeenCalledTimes(2)
  })

  it('cancels the opening task and all queued text; a late session cannot play', async () => {
    let finish!: (session: SpeechInputSession) => void
    const player = new Player(), states: SpeechState[] = []
    const openInput = vi.fn((_entry: { text: string }, _signal: AbortSignal) => new Promise<SpeechInputSession>(resolve => { finish = resolve }))
    const createURL = vi.fn(() => 'blob:synthetic')
    const speech = new ChatReadAloud({ openInput, createPlayer: () => player, createURL, revokeURL: vi.fn(), onState: state => states.push(state) })
    speech.enqueue({ key: 'old', text: '正文' })
    const signal = openInput.mock.calls[0]![1]
    speech.stop(); expect(signal.aborted).toBe(true)
    finish({ audio: { stream: new ReadableStream<Uint8Array>({ start(c) { c.close() } }), contentType: 'audio/wav' }, append: vi.fn() }); await tick()
    expect(states.at(-1)?.status).toBe('idle')
    expect(player.play).not.toHaveBeenCalled()
    expect(createURL).not.toHaveBeenCalled()
  })

  it('ignores old play promise rejection after interruption and a new generated reply', async () => {
    const f = fixture(); let rejectOld!: (value: Error) => void
    f.player.play.mockImplementationOnce(() => new Promise((_resolve, reject) => { rejectOld = reject }))
    f.speech.enqueue({ key: 'old', text: 'old' }); await tick()
    f.speech.stop(); f.speech.enqueue({ key: 'new', text: 'new' }); await tick()
    f.player.emit('playing'); rejectOld(new Error('late')); await tick()
    expect(f.latest()).toMatchObject({ key: 'new', status: 'playing' })
    f.speech.stop(); f.player.emit('playing'); f.player.emit('ended'); f.player.emit('error')
    expect(f.latest()?.status).toBe('idle')
    expect(f.player.src).toBe('')
  })

  it('offers supported gesture resume after autoplay rejection without resynthesizing', async () => {
    const f = fixture()
    f.player.play.mockRejectedValueOnce(Object.assign(new Error('gesture required'), { name: 'NotAllowedError' }))
    f.speech.enqueue({ key: 'a', text: 'text' }); await tick()
    expect(f.latest()?.status).toBe('blocked')
    f.speech.resume()
    // play() is invoked synchronously in the user gesture, before microtasks.
    expect(f.player.play).toHaveBeenCalledTimes(2)
    expect(f.openInput).toHaveBeenCalledOnce()
    f.player.emit('playing'); expect(f.latest()?.status).toBe('playing')
    f.speech.stop()
  })

  it('a task error never retries its own text; deltas queued but never sent continue through the next task', async () => {
    const f = fixture()
    f.speech.enqueue({ key: 'a', text: 'text' }); f.speech.enqueue({ key: 'b', text: 'queued' }); await tick()
    f.player.emit('error'); await tick()
    // The failed task is released and reported; its fed text rolls back and
    // opens the next task, and the queued delta continues through it in order.
    expect(f.states.some(state => state.status === 'error')).toBe(true)
    expect(f.openInput).toHaveBeenCalledTimes(2)
    expect(f.openInput.mock.calls.map(call => call[0]!.text)).toEqual(['text', 'text'])
    expect(f.revokeURL).toHaveBeenCalledOnce()
    f.speech.stop()
    // A host that decides a failure is terminal discards the queue from the
    // error notification: nothing of that reply continues.
    const states: SpeechState[] = [], player = new Player()
    const openInput = vi.fn(async (_entry: { text: string }, _signal: AbortSignal): Promise<SpeechInputSession> => { throw new Error('lost response') })
    const speech = new ChatReadAloud({ openInput, createPlayer: () => player, createURL: () => 'blob:synthetic', revokeURL: vi.fn(), onState: state => { states.push(state); if (state.status === 'error') speech.discard() } })
    speech.enqueue({ key: 'lost', text: 'text' }); speech.enqueue({ key: 'lost', text: 'more' }); await tick()
    expect(states.at(-1)?.status).toBe('error'); expect(openInput).toHaveBeenCalledOnce()
  })

  it('splits only at the protocol frame limit by Unicode code points and never drops text', () => {
    const text = '🙂'.repeat(45001)
    const frames = speechInputFrames(text)
    expect(frames.map(frame => Array.from(frame).length)).toEqual([20000, 20000, 5001])
    expect(frames.join('')).toBe(text)
    expect(speechInputFrames('')).toEqual([])
    expect(speechInputFrames('中'.repeat(20000))).toHaveLength(1)
  })
  it('sends one whole-text job to a single native task instead of per-chunk requests', async () => {
    const f = fixture(); f.speech.setLive(['row'])
    f.speech.enqueue({ key: 'turn', messageId: 'row', text: '甲'.repeat(45001) }); await tick()
    // The first protocol frame opens the task; the remainder is appended.
    expect(f.openInput).toHaveBeenCalledOnce()
    expect(Array.from(f.openInput.mock.calls[0]![0]!.text).length).toBe(20000)
    expect(f.frames.map(frame => [frame.sequence, Array.from(frame.text).length])).toEqual([[1, 20000], [2, 5001]])
    expect(f.frames.every(frame => !frame.final)).toBe(true)
    f.speech.setLive([]); await tick()
    expect(f.frames.at(-1)).toEqual({ sequence: 3, offset: 45001, text: '', final: true })
    f.speech.stop()
  })
})

describe('live reply eligibility (I8 completion reads + B1 pagination gate)', () => {
  const start = (history: ChatAssistantTurn[] = []) => {
    const replies = new LiveSpeechReplies()
    // B-α: entering a scope absorbs every row already present.
    expect(replies.update(history, true, false)).toEqual([])
    return replies
  }
  it('reads a row that completes after load, never having observed a streaming frame (R1)', () => {
    const replies = start()
    replies.update([reply('think', true, '长思考')], true, false)
    const done = reply('think', false, '长思考后的完整回复。')
    expect(replies.update([done], true, false)).toEqual([{ key: speechKey(done), messageId: 'think', text: '长思考后的完整回复。' }])
    expect(replies.update([done], true, false)).toEqual([])
  })
  it('absorbs a streaming row during a history-load window, then reads it when it completes (B-β + R1 priority)', () => {
    const replies = start()
    expect(replies.update([reply('refresh', true, '前半句。')], true, true)).toEqual([])
    expect(replies.update([reply('refresh', true, '前半句。后续')], true, true)).toEqual([])
    const done = reply('refresh', false, '前半句。后续完成。')
    expect(replies.update([done], true, false)).toEqual([{ key: speechKey(done), messageId: 'refresh', text: '前半句。后续完成。' }])
  })
  it('never reads prepended history pages or mid-inserted rows, even across later ticks (B-γ)', () => {
    const replies = start()
    expect(replies.update([reply('tail', true, '尾部进行中')], true, false)).toEqual([])
    const older = reply('older-page', false, '几周前的旧消息。')
    expect(replies.update([older, reply('tail', true, '尾部进行中')], true, false)).toEqual([])
    const middle = reply('middle-insert', false, '中插行。')
    expect(replies.update([older, middle, reply('tail', true, '尾部进行中')], true, false)).toEqual([])
    const finishedTail = reply('tail', false, '尾部完成。')
    expect(replies.update([older, middle, finishedTail], true, false)).toEqual([{ key: speechKey(finishedTail), messageId: 'tail', text: '尾部完成。' }])
  })
  it('reads a completed row that arrives at the tail without ever streaming (R3)', () => {
    const replies = start()
    const fresh = reply('fast', false, '两次 tick 之间就完成的回复。')
    expect(replies.update([fresh], true, false)).toEqual([{ key: speechKey(fresh), messageId: 'fast', text: '两次 tick 之间就完成的回复。' }])
    expect(replies.update([fresh], true, false)).toEqual([])
  })
  it('reads a retry that replaces the optimistic row by a new tail id (R3, not R2)', () => {
    const replies = start()
    expect(replies.update([reply('optimistic', true, '')], true, false)).toEqual([])
    const replacement = reply('server-row', false, '重试后的正式回复。')
    expect(replies.update([replacement], true, false)).toEqual([{ key: speechKey(replacement), messageId: 'server-row', text: '重试后的正式回复。' }])
  })
  it('reads a revision change on an existing row and never revives an interrupted run (R2)', () => {
    const replies = start()
    const first = { ...reply('one', true, ''), runtimeRunId: 'old-run', invocationId: 'invocation' }
    expect(replies.update([first], true, false)).toEqual([])
    replies.interrupt([first])
    const steered = { ...reply('one', true, ''), runtimeRunId: 'old-run' }
    expect(replies.update([steered], true, false)).toEqual([])
    expect(replies.update([{ ...steered, streaming: false }], true, false)).toEqual([])
    const retry = { ...reply('one', true, ''), runtimeRunId: 'retry-run', invocationId: 'retry-invocation' }
    expect(replies.update([retry], true, false)).toEqual([])
    const retried = { ...retry, streaming: false, messages: [{ id: 1, type: 'text' as const, content: '新一次运行的回复。' }] }
    expect(replies.update([retried], true, false)).toEqual([{ key: speechKey(retried), messageId: 'one', text: '新一次运行的回复。' }])
  })
  it('keeps known rows through wholesale array replacement (reconciliation never rereads)', () => {
    const replies = start()
    expect(replies.update([reply('live', true, '第一句。后续')], true, false)).toEqual([{ key: 'turn:live', messageId: 'live', text: '第一句。' }])
    const settled = { ...reply('live', false, '第一句。整段完成。'), serverId: 'persisted-render-id' }
    expect(replies.update([settled], true, false)).toEqual([{ key: 'turn:live', messageId: 'live', text: '整段完成。' }])
    const replaced = { ...settled, serverId: 'persisted-render-id-2' }
    expect(replies.update([replaced], true, false)).toEqual([])
  })
  it('rebuilds the baseline after scope reset', () => {
    const replies = start()
    const fresh = reply('fresh', false, '新会话的完成回复。')
    expect(replies.update([fresh], true, false)).toEqual([{ key: speechKey(fresh), messageId: 'fresh', text: '新会话的完成回复。' }])
    replies.reset()
    expect(replies.update([reply('history-after-reset', false, '重置后的历史。')], true, false)).toEqual([])
  })
  it('skips error blocks and never reads rows completed while inactive', () => {
    const replies = start()
    expect(replies.update([reply('failed', true, '')], true, false)).toEqual([])
    const errored = reply('failed', false, '')
    errored.messages.push({ id: 2, type: 'error', content: 'failed' })
    expect(replies.update([errored], true, false)).toEqual([])
    expect(replies.update([reply('hidden', true, '')], false, false)).toEqual([])
    expect(replies.update([reply('hidden', false, '不可见期间完成的回复。')], true, false)).toEqual([])
  })
  it('consumes interrupted streams and pending completions; a later settled projection stays silent', () => {
    const replies = start()
    expect(replies.update([{ ...reply('old', true, '半句。后续'), runtimeRunId: 'run' }], true, false)).toEqual([{ key: 'turn:old', messageId: 'old', text: '半句。' }])
    replies.interrupt([{ ...reply('old', true, '半句。后续'), runtimeRunId: 'run' }])
    expect(replies.update([{ ...reply('old', false, '半句。完成。'), runtimeRunId: 'run' }], true, false)).toEqual([])
    expect(replies.update([reply('old', false, '半句。完成。')], true, false)).toEqual([])
  })
})

