import { markRuntimeTurn } from '@/store/chat/runtime-transcript-merge'
import type { RuntimeCurrentRunView, UIMessage } from '@/composables/api/useChat.types'

function reply(text: string, streaming = true): ChatAssistantTurn {
  return { id: 'render', turnId: 'turn', runtimeRunId: 'run', role: 'assistant', timestamp: '', streaming, messages: [{ id: 0, type: 'text', content: text }] }
}
// Frames derived from the real runtime projection chain the chat store uses:
// projectRuntimeTranscript keeps the conversation_ack status block only while
// the run is active and appends it after every content block regardless of
// arrival order, and drops it entirely once the run settles; markRuntimeTurn
// stamps the run id and the streaming flag exactly as applyRuntimeTranscript
// does. Ack and terminal-frame fixtures must come from here, never from a
// hand-written block order — a settled frame really has no status block.
let seed = 0
const replyText = (content: string): UIMessage => ({ id: ++seed, type: 'text', content })
const ackLine = (text: string): UIMessage => ({ id: 0, type: 'status', name: 'conversation_ack', args: { text } })
const projectedReply = (status: 'running' | 'completed', blocks: UIMessage[]): ChatAssistantTurn => {
  const run: RuntimeCurrentRunView = {
    run_id: 'run', turn_id: 'turn', turn_position: 1, generation: 'g', status,
    started_at: '2026-11-01T00:00:00Z', updated_at: '2026-11-01T00:00:00Z', messages: blocks,
  }
  const slice = projectRuntimeTranscript(run, { botId: 'bot', sessionId: 'session' })
  const segment = slice.turns.at(-1)!
  if (segment.role !== 'assistant') throw new Error('projection carried no assistant segment')
  const turn: ChatAssistantTurn = {
    id: 'render', turnId: segment.turn_id, turnPosition: segment.turn_position, role: 'assistant',
    // The projected blocks here are text/status only; their wire shape maps
    // one-to-one onto the store's content blocks (normalizeUIMessage copies
    // both verbatim).
    messages: segment.messages.map(block => ({ ...block })) as ChatAssistantTurn['messages'],
    timestamp: segment.timestamp, streaming: false,
  }
  return markRuntimeTurn(turn, slice, false) as ChatAssistantTurn
}
