    let clock = 0
    const live = new LiveSpeechReplies({ now: () => clock })
    live.update([], true, false)
    // The first completed span always ships alone, however short it is.
    expect(live.update([reply('第一句。甲。后续')], true, false)).toEqual([{ key: 'turn', messageId: 'render', text: '第一句。甲。' }])
    // A later short completed sentence stays held, waiting for more text.
    expect(live.update([reply('第一句。甲。乙。后续')], true, false)).toEqual([])
    expect(live.holdRemaining()).toBe(1500)
    // The hold expiring releases exactly the completed span that waited.
    clock = 1600
    expect(live.update([reply('第一句。甲。乙。丙。后续')], true, false)).toEqual([{ key: 'turn', messageId: 'render', text: '乙。丙。' }])
    expect(live.holdRemaining()).toBeUndefined()
  })
  it('a held short span leaves with its run: a retry (R2) or a dropped row never reports a stale hold', () => {
    let clock = 0
    const live = new LiveSpeechReplies({ now: () => clock })
    live.update([], true, false)
    expect(live.update([reply('第一句。甲。后续')], true, false)).toEqual([{ key: 'turn', messageId: 'render', text: '第一句。甲。' }])
    expect(live.update([reply('第一句。甲。乙。后续')], true, false)).toEqual([])
    expect(live.holdRemaining()).toBe(1500)
    // Retry/steer replaces the run on the same row: the old cursor and hold go.
    clock = 5000
    expect(live.update([{ ...reply('重试后的回复。开头'), runtimeRunId: 'run-2' }], true, false)).toEqual([])
    expect(live.holdRemaining()).toBeUndefined()
    // A row dropped from the array (an abandoned turn replaced wholesale)
    // takes its hold with it as well.
    const dropped = new LiveSpeechReplies({ now: () => clock })
    dropped.update([], true, false)
    dropped.update([reply('第一句。甲。后续')], true, false)
    expect(dropped.update([reply('第一句。甲。乙。后续')], true, false)).toEqual([])
    expect(dropped.holdRemaining()).toBe(1500)
    clock = 9000
    expect(dropped.update([], true, false)).toEqual([])
    expect(dropped.holdRemaining()).toBeUndefined()
  })
  it('a tool step flushes the pending tail even under the batching minimum', () => {
    const live = new LiveSpeechReplies()
    live.update([], true, false)
    expect(live.update([reply('第一句。马上')], true, false)).toEqual([{ key: 'turn', messageId: 'render', text: '第一句。' }])
    const tool = { type: 'tool', id: 1, name: 'shell', toolName: 'shell', toolCallId: 'call', input: {}, running: true, done: false } as unknown as ChatAssistantTurn['messages'][number]
    const withTool: ChatAssistantTurn = { ...reply('', true), messages: [{ type: 'text', id: 0, content: '第一句。马上' }, tool] }
    // The newest block is a tool call: the incomplete tail sentence is
    // complete text now and flushes whole instead of hanging until settle.
    expect(live.update([withTool], true, false)).toEqual([{ key: 'turn', messageId: 'render', text: '马上' }])
  })
})
