  const openInput = vi.fn(async (_entry: { text: string }, _signal: AbortSignal) => ({ audio: { stream, contentType: 'audio/wav' }, append: vi.fn() }))
  const createURL = vi.fn((_source: Blob | MediaSource) => 'blob:wav')
  const revokeURL = vi.fn()
  const speech = new ChatReadAloud({ openInput, createPlayer: () => player, createURL, revokeURL, onState: state => states.push(state) })
  return { feed, cancel, player, states, openInput, createURL, revokeURL, speech, stream }
}

it('preserves WAV type and bytes through one response; creates no Blob URL before EOF', async () => {
  const f = fixture()
  f.speech.enqueue({ key: 'wav', text: 'visible' })
