  expect(f.openInput.mock.calls.map(call => call[0].text)).toEqual(['visible', 'old queue'])
  expect(f.openInput.mock.calls[0]![1].aborted).toBe(true)
})

it('a Blob URL allocation error stays the first error, does not retry its text, and lets queued text continue', async () => {
  const f = fixture(), reason = new Error('first URL failure')
