it('native decode failure after Blob preparation clears the URL without resynthesis of that text; queued text continues', async () => {
  const f = fixture()
  f.speech.enqueue({ key: 'wav', text: 'visible' }); f.speech.enqueue({ key: 'later', text: 'old queue' })
  f.feed.close(); await tick(); f.player.dispatchEvent(new Event('error')); await tick()
  expect(f.states).toContainEqual(expect.objectContaining({ key: 'wav', status: 'error' }))
