// @vitest-environment jsdom
import { createApp, h, nextTick, ref, type App } from 'vue'
import { useLocalStorage } from '@vueuse/core'
import { afterEach, beforeEach, expect, it, vi } from 'vitest'
import type { ChatAssistantTurn, ChatMessage } from '@/store/chat/types'
import { useChatReadAloud } from './useChatReadAloud'
import { createTranscriptHistory } from '@/store/chat/transcript-history'

const api = vi.hoisted(() => ({ config: vi.fn(), start: vi.fn(), append: vi.fn() }))
vi.mock('@memohai/sdk', () => ({ getBotsByBotIdTtsPlaybackConfig: api.config, postBotsByBotIdTtsPlaybackInput: api.start, putBotsByBotIdTtsPlaybackInput: api.append }))
let app: App | undefined, root: HTMLDivElement | undefined
const players: (EventTarget & { src: string, play: ReturnType<typeof vi.fn> })[] = []
const tick = async () => { await nextTick(); for (let i = 0; i < 40; i++) await Promise.resolve(); await nextTick() }
const message = (id: string, content: string, streaming = true): ChatAssistantTurn => ({ id, turnId: id, runtimeRunId: 'run-' + id, role: 'assistant', streaming, timestamp: '', messages: [{ id: 0, type: 'text', content }] })
beforeEach(() => {
  localStorage.setItem('token', 'isolated-account-one'); players.length = 0
  api.config.mockReset().mockResolvedValue({ data: { identity: 'original-config', input_content_type: 'audio/mpeg' }, response: { ok: true } })
  api.start.mockReset().mockImplementation(async () => ({ data: new ReadableStream({ start(c) { c.enqueue(new Uint8Array([1, 2, 3])); c.close() } }), response: new Response(null, { headers: { 'Content-Type': 'audio/mpeg', 'X-Speech-Playback-Identity': 'original-config' } }) }))
  api.append.mockReset().mockResolvedValue({ response: new Response(null, { status: 204 }) })
  vi.stubGlobal('Audio', class extends EventTarget { src = ''; play = vi.fn(async () => {}); pause() {}; load() {}; constructor() { super(); players.push(this) } })
  vi.stubGlobal('URL', { createObjectURL: vi.fn(() => 'blob:cached-audio'), revokeObjectURL: vi.fn() })
})
afterEach(() => { app?.unmount(); app = undefined; root?.remove(); vi.unstubAllGlobals(); localStorage.clear() })
function mount(initial: ChatMessage[] = [message('history', 'History.', false)]) {
  const messages = ref<ChatMessage[]>(initial), scope = ref('bot:session'), draft = ref('')
  let speech!: ReturnType<typeof useChatReadAloud>
  root = document.createElement('div'); document.body.append(root)
  app = createApp({ setup() {
    speech = useChatReadAloud({ nativeInput: true, botId: ref('bot'), scope, modelId: ref('configured-model'), enabled: ref(true), loading: ref(false), messages, draft })
    return () => h('div')
  } }); app.mount(root)
  return { messages, scope, draft, get speech() { return speech } }
}
async function automatic(f: ReturnType<typeof mount>) {
  f.messages.value.push(message('live', '')); await tick()
  f.messages.value[1] = message('live', 'Fresh complete reply.', false); await tick()
  expect(f.speech.canReplay(f.messages.value[1]!)).toBe(true)
}
it('opens one task for an uncached reply on demand, then replays saved bytes after stop without another generation', async () => {
  const f = mount(); await tick()
  expect(f.speech.canReplay(f.messages.value[0]!)).toBe(true)
  await f.speech.replay(f.messages.value[0]!); await tick()
  expect(api.config).toHaveBeenCalledOnce(); expect(api.start).toHaveBeenCalledOnce()
  expect(api.start.mock.calls[0]![0].body.text).toBe('History.')
  await automatic(f); f.speech.stop()
  await f.speech.replay(f.messages.value[1]!); await tick()
  // The capability cache serves the second task; only the replay identity
  // check would fetch again, and this reply was never generated before.
  expect(api.config).toHaveBeenCalledOnce(); expect(api.start).toHaveBeenCalledTimes(2)
  expect(players[0]!.play).toHaveBeenCalledTimes(2)
})
it('re-synthesizes a cached reply when the server voice identity changes', async () => {
  const f = mount(); await tick(); await automatic(f); f.speech.stop()
  await f.speech.replay(f.messages.value[1]!); await tick()
  expect(api.start).toHaveBeenCalledOnce()
  api.config.mockResolvedValueOnce({ data: { identity: 'changed-voice-format', input_content_type: 'audio/mpeg' }, response: { ok: true } }); f.speech.stop()
  await f.speech.replay(f.messages.value[1]!); await tick()
  expect(api.start).toHaveBeenCalledTimes(2)
  expect(api.start.mock.calls[1]![0].body.text).toBe('Fresh complete reply.')
  expect(players[0]!.play).toHaveBeenCalledTimes(3)
  expect(f.speech.canReplay(f.messages.value[1]!)).toBe(true)
})
it('typing does not fence a late replay validation; scope cancellation fences it and a new account cannot inherit cached audio', async () => {
  const f = mount(); await tick(); await automatic(f); f.speech.stop()
  let complete!: (value: { data: { identity: string, input_content_type: string }, response?: unknown }) => void
  api.config.mockImplementationOnce(() => new Promise(done => { complete = done }))
  const pending = f.speech.replay(f.messages.value[1]!)
  const signal = api.config.mock.calls.at(-1)![0].signal as AbortSignal
  f.draft.value = 'interrupt'; expect(signal.aborted).toBe(false)
  f.scope.value = 'bot:other-session'; expect(signal.aborted).toBe(true)
  complete({ data: { identity: 'original-config', input_content_type: 'audio/mpeg' }, response: { ok: true } }); await pending; await tick()
  expect(players[0]!.play).toHaveBeenCalledOnce(); expect(api.start).toHaveBeenCalledOnce()
  f.draft.value = ''; f.scope.value = 'bot:session'; await tick()
  expect(f.speech.canReplay(f.messages.value[1]!)).toBe(true)
  f.scope.value = 'bot:other-session'; await tick()
  expect(f.speech.canReplay(f.messages.value[1]!)).toBe(true)
  const account = useLocalStorage('token', ''); account.value = 'isolated-account-two'; await tick()
  expect(f.speech.canReplay(f.messages.value[1]!)).toBe(true)
  await f.speech.replay(f.messages.value[1]!); await tick()
  expect(api.start).toHaveBeenCalledTimes(2)
  expect(api.start.mock.calls[1]![0].body.text).toBe('Fresh complete reply.')
})
it('keeps the generated run identity through the real settled-history reconciliation', async () => {
  const f = mount(); await tick(); await automatic(f); f.speech.stop()
  const history = createTranscriptHistory({ messages: f.messages.value, rememberBackgroundTask: task => task, applyPendingBackgroundEventsToTool() {} })
  history.replaceMessages([{ id: 'persisted-live', turn_id: 'live', role: 'assistant', timestamp: '', messages: [{ id: 0, type: 'text', content: 'Fresh complete reply.' }] }])
  await tick()
  expect(f.messages.value[0]!.id).toBe('live')
  expect(f.messages.value[0]!.serverId).toBe('persisted-live')
  expect(f.speech.canReplay(f.messages.value[0]!)).toBe(true)
  await f.speech.replay(f.messages.value[0]!); await tick()
  expect(api.start).toHaveBeenCalledOnce(); expect(api.config).toHaveBeenCalledTimes(2)
})
it('a native direct token replacement cannot reuse another account cache even without a storage event', async () => {
  const f = mount(); await tick(); await automatic(f); f.speech.stop()
  localStorage.setItem('token', 'native-account-two')
  expect(f.speech.canReplay(f.messages.value[1]!)).toBe(true)
  await f.speech.replay(f.messages.value[1]!); await tick()
  expect(api.config).toHaveBeenCalledTimes(2); expect(api.start).toHaveBeenCalledTimes(2)
  expect(api.start.mock.calls[1]![0].body.text).toBe('Fresh complete reply.')
})

it('keeps sibling rows in one turn/run distinct for tasks, cache and the single active bubble', async () => {
