// @vitest-environment jsdom
import { createApp, defineComponent, h, nextTick, ref, type App } from 'vue'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import type { ChatMessage } from '@/store/chat/types'
import { setupApiClient } from '@/lib/api-client'
import { useChatReadAloud } from './useChatReadAloud'
const requests: Request[] = []
const players: Player[] = []
class Player extends EventTarget {
 src = ''
 play = vi.fn(async () => {})
 pause = vi.fn()
 load = vi.fn()
}
let app: App | undefined, root: HTMLDivElement | undefined
const tick = async () => { await nextTick(); for (let i = 0; i < 30; i++) await Promise.resolve(); await nextTick() }
const bot='10000000-0000-4000-8000-000000000001'
const message=(streaming: boolean): Extract<ChatMessage, {role:'assistant'}> => ({id:'reply',turnId:'turn',runtimeRunId:'run',role:'assistant',timestamp:'',streaming,messages:[{id:0,type:'text',content:'手机端合成验证'}]})
function audioStreamResponse() {
 // The native task answers headered first and streams the body without a length.
 const stream = new ReadableStream<Uint8Array>({ start(c) { c.enqueue(new TextEncoder().encode('synthetic audio')); c.close() } })
 return new Response(stream, { status: 200, headers: { 'Content-Type': 'audio/mpeg', 'X-Speech-Playback-Identity': 'configured' } })
}
function capabilityResponse() {
 return new Response(JSON.stringify({ identity: 'configured', input_content_type: 'audio/mpeg' }), { status: 200, headers: { 'Content-Type': 'application/json' } })
}
beforeEach(()=>{
 requests.length=0;players.length=0
 localStorage.setItem('token','synthetic-isolated-token')
 vi.stubGlobal('Audio',class extends Player {constructor(){super();players.push(this)}})
 vi.spyOn(URL,'createObjectURL').mockReturnValue('blob:synthetic-playback')
 vi.spyOn(URL,'revokeObjectURL').mockImplementation(()=>{})
})
afterEach(()=>{app?.unmount();app=undefined;root?.remove();localStorage.clear();vi.restoreAllMocks();vi.unstubAllGlobals()})
function mount(fetcher: typeof fetch, initial: ChatMessage[] = []) {
 setupApiClient({baseUrl:'https://api.example.invalid/api',fetch:fetcher})
 const messages=ref<ChatMessage[]>(initial),draft=ref('');let speech!: ReturnType<typeof useChatReadAloud>
 root=document.createElement('div');document.body.append(root)
 app=createApp(defineComponent({setup(){speech=useChatReadAloud({nativeInput:true,botId:ref(bot),scope:ref(bot+':original-session'),enabled:ref(true),loading:ref(false),draft,messages});return()=>h('div')}}));app.mount(root)
 return {messages,draft,speech}
}
function inputFetcher() {
 // One real-SDK task: read-only capability, streamed POST task, final PUT append.
 return vi.fn(async (input: RequestInfo|URL, init?: RequestInit) => {
  const request = new Request(input, init)
  requests.push(request)
  if (request.method === 'GET') return capabilityResponse()
  if (request.method === 'POST') return audioStreamResponse()
  return new Response(null, { status: 204 })
 })
}
describe('Harmony actual generated SDK read-aloud seam',()=>{
 it('uses the configured HTTPS API base/auth for one incremental task; history is silent and typing does not stop',async()=>{
  const fetcher=inputFetcher()
  // History present at scope entry is baseline (B-alpha) and stays silent.
  const f=mount(fetcher,[{...message(false),id:'history',turnId:'history-turn',runtimeRunId:'history-run'}]);await tick();expect(requests).toHaveLength(0)
  f.messages.value=[message(true)];await tick();f.messages.value=[message(false)];await tick()
  const [config,post,put]=requests
  expect(config!.method).toBe('GET')
  expect(config!.url).toBe(`https://api.example.invalid/api/bots/${bot}/tts/playback/config`)
  expect(config!.headers.get('authorization')).toBe('Bearer synthetic-isolated-token')
  expect(post!.method).toBe('POST')
  expect(post!.url).toBe(`https://api.example.invalid/api/bots/${bot}/tts/playback/input`)
  expect(post!.headers.get('authorization')).toBe('Bearer synthetic-isolated-token')
  const frame=await post!.clone().json()
  expect(frame).toMatchObject({sequence:0,offset:0,text:'手机端合成验证',final:false})
  expect(typeof frame.id).toBe('string')
  expect(put!.method).toBe('PUT')
  expect(await put!.clone().json()).toMatchObject({text:'',final:true})
  expect(players).toHaveLength(1)
  players[0]!.dispatchEvent(new Event('playing'));expect(f.speech.status(f.messages.value[0]!)).toBe('playing')
  f.draft.value='输入'
  expect(players[0]!.src).not.toBe('');expect(f.speech.state.value.status).toBe('playing')
 })
 it.each([403,404])('keeps HTTP%s capability failure explicit; no legacy playback or synthesize fallback, no retry',async status=>{
  const fetcher=vi.fn(async(input: RequestInfo|URL, init?: RequestInit)=>{const request=new Request(input,init);requests.push(request);return new Response('{"code":"http.not_found"}',{status,headers:{'Content-Type':'application/problem+json'}})})
  const f=mount(fetcher);f.messages.value=[message(true)];await tick();f.messages.value=[message(false)];await tick()
  expect(f.speech.state.value.status).toBe('error');expect(players).toHaveLength(0)
  expect(requests).toHaveLength(1);expect(requests[0]!.url.endsWith('/tts/playback/config')).toBe(true)
  await tick();expect(fetcher).toHaveBeenCalledTimes(1)
  expect(requests.some(r=>r.url.includes('/synthesize'))).toBe(false)
  expect(requests.some(r=>r.method==='POST'&&!r.url.includes('/input'))).toBe(false)
 })
 it('aborts the actual fetch signal on interruption and discards a late capability response',async()=>{
  let finish!: (r:Response)=>void
  const fetcher=vi.fn((input: RequestInfo|URL, init?: RequestInit)=>{requests.push(new Request(input,init));return new Promise<Response>(resolve=>{finish=resolve})})
  const f=mount(fetcher);f.messages.value=[message(true)];await tick();f.messages.value=[message(false)];await tick();expect(requests).toHaveLength(1)
  f.speech.stop();expect(requests[0]!.signal.aborted).toBe(true)
  finish(capabilityResponse());await tick()
  expect(players).toHaveLength(0);expect(f.speech.state.value.status).toBe('idle');expect(fetcher).toHaveBeenCalledTimes(1)
 })
})

