import { getMarkdown, parseMarkdownToStructure, type ParsedNode } from 'markstream-vue'
import { renderToString } from 'katex'
import { withLiteralSingleDollars } from '@/utils/markdown-dollar'

// Phone streaming projection of reply text. Structured nodes project exactly
// like the shared settled projection in speech-visible-text; only a construct
// the renderer has not structured yet can hold the tail, and it does so only
// while it can still close: within streamingHoldWindow code points of the end
// of the final top-level block. A literal | or an unclosed [ mid-paragraph used
// to hold every later sentence of the reply; the live task then idled past the
// provider's input gap limit (23 s) and the whole tail was consumed. Once reply
// content has moved past such a marker the marker is spoken literally, exactly
// as the settled projection of the same source speaks it. A marker that is
// still close to the tail keeps the shared hold, so half a link label, a
// prospective table row or an opening code fence is never spoken prematurely.
// Blocks before the final one are complete: an unclosed marker there can never
// close any more (links, references and table rows are inline to their block),
// so it is always literal. The window is structural (a length, never a delay):
// markdown constructs that close do so within their own short span.
const markdown = withLiteralSingleDollars(getMarkdown('chat-speech'))
export const streamingHoldWindow = 24

function htmlText(html: string): string {
  if (typeof document === 'undefined') return ''
  const root = document.createElement('template')
  root.innerHTML = html
  root.content.querySelectorAll('script,style,template,annotation,[hidden]').forEach(node => node.remove())
  root.content.querySelectorAll('[style]').forEach(node => {
    const style = (node as HTMLElement).style
    if (style.display === 'none' || style.visibility === 'hidden') node.remove()
  })
  return root.content.textContent ?? ''
}

interface Segment { text: string, plainText: boolean }

function collect(node: ParsedNode, segments: Segment[]): void {
  const n = node as ParsedNode & { children?: ParsedNode[], items?: ParsedNode[], cells?: ParsedNode[], rows?: ParsedNode[], header?: ParsedNode, term?: ParsedNode[], definition?: ParsedNode[], content?: string, code?: string, title?: string, tag?: string }
  if (n.type === 'image' || n.type === 'thematic_break' || n.type === 'footnote_anchor') return
  if (n.type === 'html_block' || n.type === 'html_inline') { segments.push({ text: htmlText(n.content ?? ''), plainText: false }); return }
  if (n.type === 'math_inline' || n.type === 'math_block') {
    segments.push({ text: htmlText(renderToString(n.content ?? '', { output: 'mathml', throwOnError: false })), plainText: false })
    return
  }
  if (n.type === 'footnote_reference') { segments.push({ text: String((node as ParsedNode & { id: string }).id), plainText: false }); return }
  if (n.type === 'table') {
    // Header and rows join with one newline, as in the shared projection.
    let emitted = false
    for (const item of [n.header, ...(n.rows ?? [])]) {
      if (!item) continue
      if (emitted) segments.push({ text: '\n', plainText: false })
      emitted = true
      collect(item, segments)
    }
    segments.push({ text: '\n', plainText: false })
    return
  }
  if (n.type === 'table_row') {
    for (const [index, cell] of (n.cells ?? []).entries()) {
      if (index) segments.push({ text: ' ', plainText: false })
      collect(cell, segments)
    }
    segments.push({ text: '\n', plainText: false })
    return
  }
  if (n.type === 'definition_item') {
    for (const [index, item] of [...(n.term ?? []), ...(n.definition ?? [])].entries()) {
      if (index) segments.push({ text: ' ', plainText: false })
      collect(item, segments)
    }
    segments.push({ text: '\n', plainText: false })
    return
  }
  if (n.children || n.items) {
    if (n.type === 'admonition') segments.push({ text: `${n.title ?? ''}\n`, plainText: false })
    for (const item of (n.children ?? n.items ?? [])) collect(item, segments)
    if (/^(paragraph|heading|list_item|blockquote|footnote)$/u.test(n.type)) segments.push({ text: '\n', plainText: false })
    return
  }
  if (n.type === 'hardbreak' || n.type === 'softbreak') { segments.push({ text: '\n', plainText: false }); return }
  if (n.type === 'code_block' || n.type === 'inline_code') { segments.push({ text: (n.code ?? '') + (n.type === 'code_block' ? '\n' : ''), plainText: false }); return }
  if (n.type === 'text') { segments.push({ text: n.content ?? '', plainText: true }); return }
  segments.push({ text: n.content ?? '', plainText: false })
}

// The shared pending markers: an unclosed label, a pipe, a trailing fence run
// or an unclosed tag. Near the source end they can still become structured
// nodes; further back they are literal source text.
const pendingMarkers = /\[|\||(?:^|\n)\s*(?:`{1,2}|~{1,2})$|<[A-Za-z][^>]*$/gu

/** Visible speech text for one reply text block that is still streaming. */
export function streamingSpeechText(source: string, holdWindow = streamingHoldWindow): string {
  const blocks = parseMarkdownToStructure(source, markdown)
  const output: string[] = []
  blocks.forEach((block, index) => {
    const segments: Segment[] = []
    collect(block, segments)
    if (index !== blocks.length - 1) { output.push(segments.map(segment => segment.text).join('')); return }
    // Final block: count code points after each segment up to the last
    // non-whitespace one, then hold from the first marker still within the
    // hold window of that content end.
    const remaining: number[] = segments.map(() => 0)
    let accumulated = 0, started = false
    for (let i = segments.length - 1; i >= 0; i--) {
      if (!started && !segments[i]!.text.trim()) { remaining[i] = 0; continue }
      started = true
      remaining[i] = accumulated + Array.from(segments[i]!.text).length
      accumulated = remaining[i]!
    }
    let cut = segments.length
    for (let i = 0; i < segments.length && cut === segments.length; i++) {
      const segment = segments[i]!
      if (!segment.plainText) continue
      for (const match of segment.text.matchAll(pendingMarkers)) {
        const before = Array.from(segment.text.slice(0, match.index)).length
        const marker = Array.from(match[0]).length
        if (remaining[i]! - before - marker > holdWindow) continue
        segments[i] = { text: segment.text.slice(0, match.index), plainText: true }
        cut = i
        break
      }
    }
    output.push(segments.slice(0, cut + 1).map(segment => segment.text).join(''))
  })
  return output.join('').trim()
}

// @vitest-environment jsdom
import { describe, expect, it } from 'vitest'
import { streamingSpeechText, streamingHoldWindow } from './speech-streaming-text'
import { visibleSpeechText } from './speech-visible-text'

describe('phone streaming projection keeps feeding literal markers', () => {
  it('speaks a literal pipe once reply content has moved past it', () => {
    const source = '第一句。方案 A | B 都行。第三句。第四句。第五句。第六句。第七句。'
    expect(streamingSpeechText(source)).toBe(source)
    // The same source settled through the shared projection keeps the pipe too.
    expect(visibleSpeechText(source)).toBe(source)
  })
  it('speaks an unclosed bracket once reply content has moved past it', () => {
    const source = 'a[0 是数组下标。后面还有第一句。第二句。第三句。第四句。'
    expect(streamingSpeechText(source)).toBe(source)
    expect(visibleSpeechText(source)).toBe(source)
  })
  it('still holds a marker that is close enough to close: half link, pipe row, fence', () => {
    expect(streamingSpeechText('开头 [显')).toBe('开头')
    expect(streamingSpeechText('甲 | 乙')).toBe('甲')
    expect(streamingSpeechText('正文\n```')).toBe('正文')
    expect(streamingSpeechText('见 <a hr')).toBe('见')
    expect(streamingSpeechText('开头 [显示](https://hid')).toBe('开头 显示')
  })
  it('treats markers in completed earlier blocks as literal: they can never close there', () => {
    const source = '前段 [标签。更多文字。还有一句。\n\n后文第一句。后文第二句。后文第三句。'
    expect(streamingSpeechText(source)).toBe(visibleSpeechText(source))
    expect(streamingSpeechText(source)).toContain('[标签。')
  })
  it('releases a held marker only after the hold window of code points has passed it', () => {
    const held = '第一句。方案 A |' + '字'.repeat(streamingHoldWindow)
    expect(streamingSpeechText(held)).toBe('第一句。方案 A')
    const released = '第一句。方案 A |' + '字'.repeat(streamingHoldWindow + 1)
    expect(streamingSpeechText(released)).toBe(released)
  })
  it('keeps structured content identical to the shared settled projection', () => {
    const source = '# 标题\n\n请看[文档](https://hidden.test/secret)。代码 `x < 2`。\n\n```text\nconst x = 3\n```\n\n|甲|乙|\n|-|-|\n|1|2|\n\nUS$3–6/月'
    expect(streamingSpeechText(source)).toBe(visibleSpeechText(source))
  })
})

/** Conservative streaming boundaries, using native sentence segmentation plus
 * the abbreviation/initial/decimal protection used by LiveKit's basic sentence
 * tokenizer. Pipecat's SimpleTextAggregator likewise retains ambiguous periods
 * for textual lookahead rather than committing punctuation on the token alone.
 * Sources and deliberately excluded length/delay heuristics: continuity DESIGN. */
export function completedSpeechPrefix(text: string, streaming = false): number {
  const protect = (value: string) => value.replace(/\./gu, '\u2060')
  const masked = text
    .replace(/\b(?:Mr|Mrs|Ms|Dr|St|Prof|Capt|Cpt|Lt|Inc|Ltd|Jr|Sr|Co|Ph\.D)\./gu, protect)
    .replace(/\b(?:[A-Za-z]\.){2,}/gu, protect)
    .replace(/\b[A-Z]\.(?=\s+[A-Z][\p{L}])/gu, protect)
    .replace(/[\p{L}\p{N}]\.(?=[\p{L}\p{N}])/gu, protect)
    .replace(/(?:^|\s)\d+\.(?=\s|$)/gu, protect)
    .replace(/\.{2,}/gu, protect)
  // Masks have exactly the same UTF-16 length, so offsets still name the
  // untouched visible text. No synthetic overlap is sent to TTS or read twice.
  const sentences = typeof Intl.Segmenter === 'function'
    ? Array.from(new Intl.Segmenter(undefined, { granularity: 'sentence' }).segment(masked), item => item.segment)
    : masked.match(/[^。！？.!?\n]*[。！？.!?\n]+(?:["'”’」』)）]*\s*)?|.+$/gu) ?? []
  let end = 0
  for (const sentence of sentences) {
    if (!/[\p{Sentence_Terminal}\n]["'”’」』)）]*\s*$/u.test(sentence)) break
    const next = end + sentence.length
    // As in Pipecat, punctuation alone is not enough: a following token or
    // response end resolves decimals, initials and Markdown closing delimiters.
    // The latter can still change how the renderer projects a CJK sentence.
    if (!masked.slice(next).trim()) {
      // Pipecat lookahead: a trailing bare period may still extend (3. -> 3.14,
      // J. -> J.S.), so punctuation alone never commits it. An unambiguous
      // terminal - CJK full stop/exclamation/question, Latin !?, a newline, or
      // closers after one of them - cannot be un-sentenced by later text. In
      // streaming mode such a trailing sentence commits at once: the first
      // sentence of a reply is read when it completes instead of waiting for
      // the second sentence to begin, and every later commit keeps the one
      // task's continue-task gap short instead of stretching it toward the
      // provider's input-idle budget. Settled frames keep the strict rule.
      if (!(streaming && /[。！？!?\n]["'”’〉》」』)\]]*\s*$/u.test(sentence))) break
    }
    end = next
  }
  if (streaming && end === 0) {
    // The segmenter can hold a short line - a heading, a list item - as one
    // unterminated segment even after a hard line break ended it. A trailing
    // newline cannot be undone by later text, so commit through it.
    if (/[ \t]*\n[ \t]*$/u.test(masked)) return masked.length
  }
  return end
}

/** Opt-in, bounded, page-memory diagnostics. Never retain text, URLs, message
 * identities, audio bytes or credentials. Durations use one performance clock. */
export type SpeechTimingEvent = 'audio_signature' | 'source_branch' | 'operation_start' | 'text_observed' | 'text_chunk_ready' | 'request_start' | 'response_headers' | 'client_first_bytes' | 'decoder_append_start' | 'decoder_append_done' | 'native_play_call' | 'native_playing' | 'native_ended' | 'body_eof' | 'blob_ready' | 'interrupted' | 'error' | 'blocked' | 'input_frame_sent' | 'task_failed'
interface TimingData { signature?: 'id3_prefix' | 'mpeg_header_prefix' | 'riff_wave_prefix' | 'unknown', bytes?: number, serverFirstAudioMS?: number, branch?: 'mse' | 'blob', mime?: 'mp3' | 'wav' | 'pcm' | 'opus' | 'other', sequence?: number, offset?: number, codepoints?: number, final?: boolean, cause?: string }
interface TimingRecord { id: string, operationId: string, trigger: 'manual' | 'automatic' | 'direct', clock: 'browser-performance', startMS: number, events: ({ event: SpeechTimingEvent, ms: number } & TimingData)[] }
export interface SpeechTiming { id: string, mark(event: SpeechTimingEvent, data?: TimingData): void, fork(): SpeechTiming }
const records: TimingRecord[] = []
const limit = 32
function enabled() { try { return typeof window !== 'undefined' && sessionStorage.getItem('memoh.speechTiming') === '1' && typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function' } catch { return false } }
function randomID() {
  if (typeof crypto.randomUUID === 'function') return crypto.randomUUID()
  const bytes = crypto.getRandomValues(new Uint8Array(16))
  bytes[6] = (bytes[6]! & 15) | 64; bytes[8] = (bytes[8]! & 63) | 128
  const hex = [...bytes].map(value => value.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}
export function beginSpeechTiming(trigger: TimingRecord['trigger']): SpeechTiming | undefined {
  if (!enabled()) return
  const start = performance.now(), operationId = randomID()
  // Console export only. No fetch, audio action, UI or persistent content log.
  Object.defineProperty(window, '__memohSpeechTiming', { configurable: true, value: { snapshot: () => JSON.parse(JSON.stringify(records)), clear: () => { records.length = 0 } } })
  function create(id: string): SpeechTiming {
    const record: TimingRecord = { id, operationId, trigger, clock: 'browser-performance', startMS: start, events: [] }
    records.push(record); if (records.length > limit) records.shift()
    // Per-frame events repeat for every accepted sequence; every other event
    // stays once per record so the bounded export cannot be flooded.
    const seen = new Set<string>()
    return { id, mark(event, data = {}) { const once = data.sequence !== undefined ? `${event}:${data.sequence}:${data.final === true}` : event; if (seen.has(once)) return; seen.add(once); record.events.push({ event, ms: performance.now() - start, ...data }) }, fork: () => create(randomID()) }
  }
  const result = create(operationId); result.mark('operation_start'); return result
}
export function speechMimeClass(type: string): TimingData['mime'] {
  const mime = type.split(';', 1)[0]?.trim().toLowerCase()
  return mime === 'audio/mpeg' || mime === 'audio/mp3' ? 'mp3' : mime === 'audio/wav' || mime === 'audio/x-wav' ? 'wav' : mime === 'audio/pcm' ? 'pcm' : mime === 'audio/opus' ? 'opus' : 'other'
}
export function serverFirstAudioMS(header: string | null): number | undefined {
  const match = /(?:^|,)\s*speech_first_audio;dur=(\d+(?:\.\d+)?)(?:\s*,|\s*$)/u.exec(header ?? '')
  return match ? Number(match[1]) : undefined
}

/** Classify only a bounded header prefix; never retain it in the export. This
 * is a signature hint, not a verified codec or a playback capability gate. */
export function audioTimingObserver(timing?: SpeechTiming) {
  const prefix: number[] = []
  return (chunk: Uint8Array) => {
    if (!timing || !chunk.length) return
    timing.mark('client_first_bytes', { bytes: chunk.length })
    if (prefix.length >= 12) return
    for (let i = 0; i < chunk.length && prefix.length < 12; i++) prefix.push(chunk[i]!)
    if (prefix.length === 12) {
      const signature = prefix[0] === 73 && prefix[1] === 68 && prefix[2] === 51 ? 'id3_prefix'
        : prefix[0] === 255 && (prefix[1]! & 224) === 224 ? 'mpeg_header_prefix'
          : prefix.slice(0, 4).join() === '82,73,70,70' && prefix.slice(8).join() === '87,65,86,69' ? 'riff_wave_prefix' : 'unknown'
      timing.mark('audio_signature', { signature })
    }
  }
}

import { describe, expect, it, vi } from 'vitest'
import type { ChatAssistantTurn } from '@/store/chat/types'
import { ChatReadAloud, LiveSpeechReplies, type SpeechInputFrame, type SpeechInputSession, type SpeechState } from './chat-read-aloud'

/** Field acceptance gates (2026-11-02, HAP41 incidents E2/E2c/E2d). These drive
 * the composed phone artifact sources directly: the streaming collect path
 * (LiveSpeechReplies) feeding the real task controller (ChatReadAloud) with a
 * recording native input, exactly as useChatReadAloud wires them. */
class Player extends EventTarget {
  src = ''
  play = vi.fn(async () => {})
  pause = vi.fn()
  load = vi.fn()
  emit(type: string) { this.dispatchEvent(new Event(type)) }
}
const tick = async () => { for (let i = 0; i < 30; i++) await Promise.resolve() }
interface FixtureOptions { holdAppend?: () => Promise<void> }
function fixture(options: FixtureOptions = {}) {
  const posts: string[] = [], puts: SpeechInputFrame[] = []
  const player = new Player(), states: SpeechState[] = []
  const openInput = vi.fn(async (entry: { text: string }): Promise<SpeechInputSession> => {
    posts.push(entry.text)
    return {
      audio: { stream: new ReadableStream<Uint8Array>({ start(c) { c.enqueue(new Uint8Array([1])); c.close() } }), contentType: 'audio/mpeg', identity: 'id-1', sequential: true },
      append: async (frame: SpeechInputFrame) => {
        if (options.holdAppend) await options.holdAppend()
        puts.push(frame)
      },
    }
  })
  const speech = new ChatReadAloud({ openInput, createPlayer: () => player, createURL: () => 'blob:synthetic', revokeURL: () => {}, onState: state => states.push(state) })
  return { speech, player, posts, puts, states }
}
function reply(content: string, streaming = true): ChatAssistantTurn {
  return { id: 'row', turnId: 'turn:row', role: 'assistant', streaming, timestamp: '', messages: [{ id: 1, type: 'text', content }] }
}
const SENTENCES = ['第一段话详细说明了今天上午在路上遇到的全部情况。', '第二段话完整列出了三个需要后续跟进的要点事项。', '第三段话给出了目前可以确认的结论与处理意见。', '第四段话是最后需要补充说明的风险与提醒内容。']

describe('field gate E2: the first completed sentence opens the speech task in its own collect tick', () => {
  it('POSTs the first sentence as soon as it completes mid-stream, and still withholds an ambiguous trailing period', async () => {
    const replies = new LiveSpeechReplies()
    expect(replies.update([], true, false)).toEqual([])
    expect(replies.update([reply('')], true, false)).toEqual([])
    const { speech, posts } = fixture()
    speech.setLive(['row'])
    for (const delta of replies.update([reply('这是第一句话。')], true, false)) speech.enqueue({ ...delta, cacheKey: 'k' })
    expect(posts, 'first completed sentence must open the task immediately').toEqual(['这是第一句话。'])
    expect(replies.update([reply('这是第一句话。价格为3.')], true, false), 'ambiguous trailing period is never committed on punctuation alone').toEqual([])
    speech.stop()
  })
})

describe('field gate E2c: a long reply never loses its middle to a failed task', () => {
  it('a task that fails mid-reply rolls its fed text back: the same text reappears in the next task', async () => {
    const replies = new LiveSpeechReplies()
    replies.update([], true, false)
    replies.update([reply('')], true, false)
    const { speech, player, posts, puts, states } = fixture()
    speech.setLive(['row'])
    for (const delta of replies.update([reply(SENTENCES[0]!)], true, false)) speech.enqueue({ ...delta, cacheKey: 'k' })
    await tick()
    // The second sentence is appended into the open task, then the task dies
    // (player error / truncated stream): its whole fed text must be re-read.
    for (const delta of replies.update([reply(SENTENCES[0]! + SENTENCES[1]!)], true, false)) speech.enqueue({ ...delta, cacheKey: 'k' })
    await tick()
    player.emit('error')
    await tick()
    expect(states.some(state => state.status === 'error')).toBe(true)
    expect(posts, 'the failed task text must reappear in the next task, not be skipped').toEqual([SENTENCES[0]!, SENTENCES[0]! + SENTENCES[1]!])
    // Later text still continues, in order, after the rollback replay.
    for (const delta of replies.update([reply(SENTENCES.slice(0, 3).join(''))], true, false)) speech.enqueue({ ...delta, cacheKey: 'k' })
    await tick()
    expect(posts).toEqual([SENTENCES[0]!, SENTENCES[0]! + SENTENCES[1]!])
    expect(puts.some(frame => frame.text === SENTENCES[2]!), 'later text appends into the rollback task in order').toBe(true)
    speech.stop()
  })
  it('a settle flush that lands in a failing task is not lost forever', async () => {
    const replies = new LiveSpeechReplies()
    replies.update([], true, false)
    replies.update([reply('')], true, false)
    const { speech, player, posts } = fixture()
    speech.setLive(['row'])
    const whole = SENTENCES.join('')
    for (const delta of replies.update([reply(whole, false)], true, false)) speech.enqueue({ ...delta, cacheKey: 'k' })
    await tick()
    player.emit('error')
    await tick()
    expect(posts, 'the settled tail replays through the next task').toEqual([whole, whole])
    speech.stop()
  })
  it('every sentence commits in its own tick and the whole reply reads in order without loss', async () => {
    const replies = new LiveSpeechReplies()
    replies.update([], true, false)
    replies.update([reply('')], true, false)
    const { speech } = fixture()
    speech.setLive(['row'])
    let spoken = ''
    for (let i = 0; i < SENTENCES.length; i++) {
      const deltas = replies.update([reply(SENTENCES.slice(0, i + 1).join(''))], true, false)
      for (const delta of deltas) speech.enqueue({ ...delta, cacheKey: 'k' })
      spoken += deltas.map(delta => delta.text).join('')
      expect(spoken, `sentence ${i + 1} must ship in its own tick, not one sentence late`).toContain(SENTENCES[i])
    }
    spoken += replies.update([reply(SENTENCES.join(''), false)], true, false).map(delta => delta.text).join('')
    expect(spoken).toBe(SENTENCES.join(''))
    await tick()
    speech.stop()
  })
  it('a premature ended never aborts the in-flight append into a failure', async () => {
    const replies = new LiveSpeechReplies()
    replies.update([], true, false)
    replies.update([reply('')], true, false)
    let release!: () => void
    const gate = new Promise<void>(resolve => { release = resolve })
    const { speech, player, posts, puts, states } = fixture({ holdAppend: () => gate })
    speech.setLive(['row'])
    for (const delta of replies.update([reply(SENTENCES[0]!)], true, false)) speech.enqueue({ ...delta, cacheKey: 'k' })
    await tick()
    // The second sentence's append is in flight when the audio ends early.
    let appended: SpeechInputFrame | undefined
    const enqueueSecond = replies.update([reply(SENTENCES[0]! + SENTENCES[1]!)], true, false)
    const appendedPromise = (async () => { await tick(); appended = puts.at(-1) })()
    for (const delta of enqueueSecond) speech.enqueue({ ...delta, cacheKey: 'k' })
    player.emit('ended')
    release()
    await Promise.all([gate, appendedPromise])
    void appended
    await tick()
    expect(states.some(state => state.status === 'error'), 'a premature ended must not manufacture a task failure').toBe(false)
    expect(posts.some(text => text === SENTENCES[0]!) || puts.some(frame => frame.text === SENTENCES[1]!), 'the racing frame is delivered exactly once, never swallowed').toBe(true)
    speech.stop()
  })
})

describe('field gate E2d: re-reading unchanged content reuses the synthesized audio', () => {
  it('a settled replay of the streamed text replays cache with no new task and the same identity', async () => {
    const replies = new LiveSpeechReplies()
    replies.update([], true, false)
    replies.update([reply('')], true, false)
    const { speech, player, posts } = fixture()
    speech.setLive(['row'])
    const text = '同一段内容，一字不差。'
    for (const delta of replies.update([reply(text)], true, false)) speech.enqueue({ ...delta, cacheKey: 'cache-1' })
    await tick()
    player.emit('playing'); player.emit('ended'); await tick()
    expect(posts).toEqual([text])
    const settled = { key: 'turn:row', messageId: 'row', text, cacheKey: 'cache-1' }
    expect(speech.replayAvailability(settled), 'unchanged text must be a cache hit').toBe('ready')
    expect(speech.replay(settled, 'id-1')).toBe(true)
    await tick()
    expect(posts, 'a cache replay never synthesizes again').toEqual([text])
    speech.stop()
  })
})

