// @vitest-environment jsdom
import { createApp, h, nextTick, ref, type App } from 'vue'
import { createI18n } from 'vue-i18n'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import type { ChatMessage } from '@/store/chat/types'
import paneSource from '../components/chat-pane.vue?raw'
import ThinkingBlock from '../components/thinking-block.vue'
// Read the real composed phone bubble-interruption expression instead of an
// external review fixture, and run it against the real disclosure control.
const messageClick = (() => {
  const match = paneSource.match(/@click\.capture="(readAloud\.stopReading\(msg, \$event\))"/u)
  if (!match?.[1]) throw new Error('Existing bubble interruption contract is missing')
  return match[1]
})()
const api = vi.hoisted(() => ({ config: vi.fn(), start: vi.fn(), append: vi.fn() }))
vi.mock('@memohai/sdk', () => ({ getBotsByBotIdTtsPlaybackConfig: api.config, postBotsByBotIdTtsPlaybackInput: api.start, putBotsByBotIdTtsPlaybackInput: api.append }))
import { useChatReadAloud } from './useChatReadAloud'

const players: Player[] = []
class Player extends EventTarget {
  src = ''
  play = vi.fn(() => Promise.reject(Object.assign(new Error('controlled autoplay rejection'), { name: 'NotAllowedError' })))
  pause = vi.fn(); load = vi.fn()
  constructor() { super(); players.push(this) }
}
class MediaFixture extends EventTarget {
  static isTypeSupported() { return true }
  readyState = 'open'
  addSourceBuffer() { const buffer = new EventTarget(); return Object.assign(buffer, { appendBuffer() { queueMicrotask(() => buffer.dispatchEvent(new Event('updateend'))) } }) }
  endOfStream() {}
}
let app: App | undefined, root: HTMLElement
const urls: string[] = [], revoke = vi.fn()
const settle = async () => { for (let i = 0; i < 20; i++) { await Promise.resolve(); await nextTick() } }
const message = (id = 'm', streaming = true, content = `正文 ${id}。`): Extract<ChatMessage, { role: 'assistant' }> => ({ id, turnId: `turn-${id}`, runtimeRunId: `run-${id}`, role: 'assistant', timestamp: '', streaming, messages: [{ id: 0, type: 'text', content }] })
beforeEach(() => {
  players.length = 0; urls.length = 0; revoke.mockClear()
  vi.useFakeTimers({ toFake: ['setTimeout', 'clearTimeout'] })
  vi.stubGlobal('ResizeObserver', class { observe() {}; unobserve() {}; disconnect() {} })
  vi.stubGlobal('Audio', Player); vi.stubGlobal('MediaSource', MediaFixture)
  vi.stubGlobal('URL', { createObjectURL: (media: MediaFixture) => { const url = `blob:same-loaded-${urls.length}`; urls.push(url); queueMicrotask(() => media.dispatchEvent(new Event('sourceopen'))); return url }, revokeObjectURL: revoke })
  api.config.mockReset().mockResolvedValue({ data: { identity: 'configured', input_content_type: 'audio/mpeg' }, response: { ok: true } })
  api.append.mockReset().mockResolvedValue({ response: new Response(null, { status: 204 }) })
  api.start.mockReset().mockResolvedValue({ data: new ReadableStream<Uint8Array>({ start(feed) { feed.enqueue(new Uint8Array([1, 2])) } }), response: { headers: new Headers({ 'Content-Type': 'audio/mpeg', 'X-Speech-Playback-Identity': 'configured' }) } })
})
afterEach(() => { app?.unmount(); app = undefined; root?.remove(); document.body.innerHTML = ''; vi.unstubAllGlobals(); vi.useRealTimers() })
function mount() {
  // Compile only the verified exact bubble-interruption expression from the
  // real pane, then run it on the capture path exactly as the pane does.
  const bubbleTap = new Function('readAloud', 'msg', '$event', messageClick) as (speech: ReturnType<typeof useChatReadAloud>, msg: ChatMessage, event: MouseEvent) => void
  const messages = ref<ChatMessage[]>([]), draft = ref(''), enabled = ref(true)
  let speech!: ReturnType<typeof useChatReadAloud>
  root = document.createElement('div'); document.body.append(root)
  app = createApp({ setup() {
    speech = useChatReadAloud({ nativeInput: true, botId: ref('bot'), scope: ref('scope'), enabled, loading: ref(false), draft, messages })
    return () => {
      const current = messages.value[0]
      return h('div', {
        'data-bubble': '',
        onClickCapture: (event: MouseEvent) => { if (current) bubbleTap(speech, current, event) },
      }, [
        h(ThinkingBlock, {
          block: { id: 7, type: 'reasoning', content: '先把第一句话想完整，然后再考虑第二句话的结构。' },
          messageId: current?.id ?? 'm',
          streaming: true,
        }),
        h('p', { 'data-bubble-body': '' }, '正文内容。'),
      ])
    }
  } })
  app.use(createI18n({
    legacy: false,
    locale: 'en',
    messages: {
      en: {
        chat: {
          thinkingInProgress: 'Thinking',
          process: { thoughtBriefly: 'Thought briefly', thoughtSeconds: 'Thought for {seconds}s' },
          readAloud: { expandThinking: 'Expand thinking', collapseThinking: 'Collapse thinking' },
        },
      },
    },
  }))
  app.mount(root)
  return { messages, draft, get speech() { return speech } }
}
async function reading() {
  const f = mount()
  f.messages.value.push(message('m', true, '正文 m。生成中'))
  await settle()
  expect(f.speech.state.value.status).toBe('blocked')
  expect(api.start).toHaveBeenCalledOnce()
  return { f, player: players[0]! }
}
describe('read-aloud interruption matrix', () => {
  it('tapping the thinking disclosure never interrupts the reply being read', async () => {
    const { f, player } = await reading(), source = player.src
    const disclosure = root.querySelector<HTMLButtonElement>('[data-reasoning-disclosure]')
    expect(disclosure, 'real disclosure control rendered inside the bubble').not.toBeNull()

    disclosure!.click(); await settle()
    expect(player.src).toBe(source)
    expect(api.start).toHaveBeenCalledOnce()
    expect(f.speech.state.value.status).toBe('blocked')
  })
  it('tapping the bubble body outside the disclosure stops the reply being read', async () => {
    const { f } = await reading()

    root.querySelector('[data-bubble-body]')!.dispatchEvent(new MouseEvent('click', { bubbles: true }))
    await settle()
    expect(f.speech.state.value.status).toBe('idle')
  })
  it('every resend path (composer send, edit resend, retry) stops the reply that is still being read', () => {
    function handlerBody(start: string, end: string): string {
      const from = paneSource.indexOf(start)
      expect(from, `${start} present in the real pane source`).toBeGreaterThan(-1)
      const to = paneSource.indexOf(end, from)
      expect(to, `${end} follows ${start}`).toBeGreaterThan(from)
      return paneSource.slice(from, to)
    }
    const resendBodies = [
      handlerBody('async function sendComposer', '\nfunction handleSendButton'),
      handlerBody('async function handleRetryMessage', 'async function handleEditMessage'),
      handlerBody('async function handleEditMessage', 'function stopReadAloudForNativeInput'),
    ]
    for (const body of resendBodies) {
      expect(body).toContain('readAloud.stop()')
      expect(body.indexOf('readAloud.stop()')).toBeLessThan(body.indexOf('chatStore.'))
    }
  })
  it('typing neither stops nor consumes the reply being read', async () => {
    const { f, player } = await reading(), source = player.src
    f.draft.value = 'new input'; await settle(); await vi.advanceTimersByTimeAsync(100)
    expect(player.src).toBe(source)
    expect(f.speech.state.value.status).toBe('blocked')
    expect(api.start).toHaveBeenCalledOnce()
  })
})

